YH_EXAM_BANKS["MGT102-CH6"] = {"id":"MGT102-CH6","short":"الفصل السادس","version":1,"los":[{"lo":"LO6-1","en":"Explain why the ability to perceive, interpret, and respond appropriately to the global environment is crucial for managerial success.","ar":"ليش فهم البيئة العالمية يحدد نجاح المدير"},{"lo":"LO6-2","en":"Differentiate between the global task and global general environments.","ar":"الفرق بين بيئة المهمة والبيئة العامة"},{"lo":"LO6-3","en":"Identify the main forces in the global task and general environments, and describe the challenges that each force presents to managers.","ar":"قوى البيئتين ووش تحدّي كل قوة"},{"lo":"LO6-4","en":"Explain why the global environment is becoming more open and competitive, and identify the forces behind the process of globalization that increase the opportunities, complexities, challenges, and threats managers face.","ar":"ليش العالم صار مفتوح وقوى العولمة"},{"lo":"LO6-5","en":"Discuss why national cultures differ and why it is important that managers be sensitive to the effects of falling trade barriers and regional trade associations on the political and social systems of nations around the world.","ar":"ثقافات الدول وأثر سقوط الحواجز التجارية"}],"sections":{"MGT102-CH6-S1":{"ar":"البيئة العالمية وبيئة المهمة","en":"The Global Environment and the Task Environment"},"MGT102-CH6-S2":{"ar":"البيئة العامة","en":"The General Environment"},"MGT102-CH6-S3":{"ar":"البيئة العالمية المتغيّرة والعولمة","en":"The Changing Global Environment"},"MGT102-CH6-S4":{"ar":"دور الثقافة الوطنية","en":"The Role of National Culture"}},"misconceptions":[{"id":"c6.global-vs-general","ar":"تخلط البيئة العالمية بالبيئة العامة","explain":"تحسب global environment وgeneral environment نفس الشي لأن الكلمتين يبدون بنفس الحرف. الـglobal environment هي الكل (task + general)، والـgeneral environment جزء منها بس: الدائرة البعيدة بقواها الخمس.","fix":"ارجع لبلوك «The Global Environment» في درس ١ واقرأ أول نقطة في الفخ، وبعدين قارن كرت C6S1-c-global-environment مع كرت C6S1-c-general-environment.","sec":"MGT102-CH6-S1","coach":"قل له «global» مرة و«general» مرة بسرعة، وهو يرد «الكل» أو «الجزء»، وبعدين يرسم لك الدايرتين ويأشّر وين كل وحدة."},{"id":"c6.task-vs-general","ar":"تحط القوة في الدائرة الغلط","explain":"تحط interest rates أو demographic forces في task environment، أو customers وcompetitors في general environment. وتقلب الصفات: task = ٤ قوى، أثرها most immediate and direct ويومي وعلى short-term decisions؛ general = ٥ قوى، أوسع وأصعب تنشاف، وتأثر على المنظمة وعلى task environment نفسها.","fix":"ارجع لبلوك «Task Environment vs. General Environment» في درس ١ وارسم Figure 6.1 من راسك: المنظمة في النص، بعدها ٤ قوى task، وبرّا ٥ قوى general (political and legal قوة وحدة)، وبعدين كروت C6S1-c-task-environment وC6S1-c-general-environment.","sec":"MGT102-CH6-S1","coach":"اقرأ له أسماء قوى مخلوطة (suppliers، inflation، customers، aging population، tariffs، distributors) وهو يقول «task» أو «general» خلال ثانيتين، وبعدها اسأله: أي وحدة تضغط عليك كل يوم؟"},{"id":"c6.task-roles-power","ar":"تخلط أدوار وقوة المورّد والموزّع","explain":"تبدّل الأدوار: suppliers يعطون input resources (حتى الموظفين ورأس المال)، وdistributors يساعدونك تبيع للزبائن، وcustomers يشترون. وتغلط في القوة: المورّد يصير قوي لما يكون sole source والمدخل vital (الشرطين مع بعض)، ولو عندك موردين كثير فأنت القوي، والموزّع الضخم زي Walmart هو اللي يضغط عليك تخفّض أسعارك.","fix":"ارجع لبلوكَي «Suppliers and Global Outsourcing» (قصة NutraSweet) و«Distributors and Customers» (Walmart ضد P&G) في درس ١ واقرأ الفخ تحت كل واحد، وبعدين كروت C6S1-c-suppliers وC6S1-c-distributors وC6S1-c-customers.","sec":"MGT102-CH6-S1","coach":"اعطه أمثلة سريعة: «جامعة تخرّج موظفين لـDell»، «Walmart تطلب تخفيض»، «Searle الوحيدة اللي تبيع NutraSweet»، وهو يسمّي الدور ويقول مين القوي وليش."},{"id":"c6.outsourcing-vs-exporting","ar":"تخلط global outsourcing بالتصدير","explain":"تحسب global outsourcing يعني تبيع برّا، وهو العكس: purchase or production of inputs or final products from overseas suppliers عشان تقلّل التكلفة وتحسّن الجودة أو التصميم (شراء أو إنتاج، مو شراء بس). أما exporting = تصنع في بلدك وتبيع برّا، وهو طريقة توسّع على Figure 6.3 مو موضوع موردين.","fix":"ارجع لبلوك «Suppliers and Global Outsourcing» في درس ١ (Apple وFoxconn، وBoeing 777 ضد 787 Dreamliner) والفخ اللي تحته، وبعدين كرت C6S1-c-global-outsourcing وكرت C6S3-c-exporting-importing ورا بعض.","sec":"MGT102-CH6-S1","coach":"قل له «Apple تخلّي Foxconn تجمّع الـiPhone في الصين» و«مصنع تمور في المدينة يبيع لأوروبا»، وخلّه يقول أي وحدة outsourcing وأي وحدة exporting، ويوريك اتجاه البضاعة بيده."},{"id":"c6.competitor-vs-potential","ar":"تخلط المنافس الحالي بالمنافس المحتمل","explain":"competitors موجودين الحين في task environment ويبيعون شي مشابه لنفس الزبائن، أما potential competitors فمو موجودين بس يقدرون يدخلون لو بغوا (زي Amazon قبل ما تبيع الأثاث). وتنسى إن rivalry هو potentially the most threatening force ونتيجته price competition وأرباح أقل.","fix":"ارجع لبلوك «Competitors and Potential Competitors» في درس ١ وركّز على مثال Amazon والأثاث وقصة صناعة الـPC، وبعدين كروت C6S1-c-competitors-rivalry وC6S1-c-potential-competitors.","sec":"MGT102-CH6-S1","coach":"اعطه حالتين: «مكتبتين في جدة يبيعون نفس الكتب» و«شركة توصيل كبيرة تقدر تبيع كتب أونلاين بس للحين ما دخلت»، وهو يحدد مين competitor ومين potential، ويقول وش يصير للأسعار لو دخلت الثانية."},{"id":"c6.barriers-reversed","ar":"تقلب علاقة حواجز الدخول بالمنافسة","explain":"تحسب إن الحواجز العالية تجيب منافسين أكثر، والصح: حواجز أعلى = دخول أصعب وأكلف = منافسين أقل = تهديد أقل وأسعار أعلى للموجودين. وكمان deregulation يخفّض الحاجز (بعده صار دخول جديد كثير في الطيران والشاحنات والاتصالات)، مو يرفعه.","fix":"ارجع لبلوك «Barriers to Entry» في درس ١ واقرأ «السلسلة المنطقية» بصوت عالي، وبعدين الفخ اللي تحته وكرت C6S1-c-barriers-to-entry.","sec":"MGT102-CH6-S1","coach":"قل له «الحاجز ارتفع» وخلّه يكمّل السلسلة كاملة: الدخول؟ عدد المنافسين؟ الأسعار؟ وبعدها قل «الحكومة سوّت deregulation» وشوف هل يقلب الاتجاه صح."},{"id":"c6.barrier-sources","ar":"تغلط في مصادر حواجز الدخول الثلاثة","explain":"المصادر ثلاثة بس في Figure 6.2: economies of scale وbrand loyalty وgovernment regulations، وكلها create barriers to entry that deter potential competitors، فلا تحط rivalry أو potential competitors مصدر. وeconomies of scale = cost advantages مو جودة، وbrand loyalty = تفضيل منتجات الشركات currently existing مو الداخلة الجديدة.","fix":"ارجع لبلوك «Barriers to Entry» في درس ١ واقرأ Figure 6.2 من اليسار لليمين: ٣ صناديق ← create barriers to entry ← that deter potential competitors، وبعدين قصة الرز الياباني كمثال على government regulations وكرت C6S1-c-barriers-to-entry.","sec":"MGT102-CH6-S1","coach":"اعطه ثلاث حالات (مصنع ضخم يشتري بالجملة، زبائن ما يغيّرون ماركتهم، الحكومة تمنع استيراد الرز) وهو يسمّي المصدر بالإنجليزي، وبعدين يرسم Figure 6.2 بأسهمه."},{"id":"c6.general-force-mixup","ar":"تحط السيناريو تحت القوة العامة الغلط","explain":"تخلط بين القوى الخمس: interest rates وinflation وunemployment = economic، وشيخوخة السكان والمواليد = demographic، والقيم والمعايير وsocial structure وموجة الصحة = sociocultural، والقوانين والـtariffs وderegulation = political and legal، وتغيّر أدوات الإنتاج والتوزيع = technological. يعني تمشي ورا كلمة في السيناريو بدل ما تشوف وش اللي تغيّر فعلاً.","fix":"ارجع لبلوك «The General Environment» في درس ٢ («القوى الخمس بنظرة وحدة»)، وبعدين مر على بلوك كل قوة، وراجع كروت C6S2-c-general-environment وC6S2-c-economic-forces وC6S2-c-demographic-forces وC6S2-c-sociocultural-forces.","sec":"MGT102-CH6-S2","coach":"اقرأ له أخبار قصيرة («البنك المركزي رفع الفائدة»، «نسبة كبار السن زادت»، «الحكومة فرضت رسوم على الاستيراد»، «الناس صاروا يهتمون بالأكل الصحي») وهو يسمّي القوة بالإنجليزي من الخمس."},{"id":"c6.one-sided-forces","ar":"تحسب القوة تهديد بس أو فرصة بس","explain":"الكتاب يقول قوى البيئة تعطي opportunities and threats مع بعض: economic وtechnological forces، وسقوط الحواجز التجارية (فرص بيع + منافسة أشد في task environment)، والاتفاقيات الإقليمية زي NAFTA (التهديد فيها بالاتجاهين). فالاختيار اللي يقول «only threats» أو «تفيد بس» غالباً هو الفخ.","fix":"ارجع لبلوك «Economic Forces» («نفس القوة تعطي فرص وتهديدات») وبلوك «Political and Legal Forces» في درس ٢، وبعدين بلوك «Distance, Culture, and Regional Trade Agreements» في درس ٣، وكروت C6S1-c-opportunities-threats وC6S3-c-regional-trade-agreements.","sec":"MGT102-CH6-S2","coach":"سمّ له قوة (ركود، تقنية جديدة، إلغاء رسوم جمركية، NAFTA) وخلّه يعطيك فرصة وحدة وتهديد واحد لكل وحدة، ولا تقبل منه طرف واحد."},{"id":"c6.tech-vs-tech-forces","ar":"تخلط التقنية بالقوى التقنية","explain":"technology هي المزيج نفسه: the combination of skills and equipment (وفي المتن tools, machines, computers, skills, information, and knowledge)، أما technological forces فهي outcomes of changes in the technology. الفخ يحط تعريف وحدة على اسم الثانية.","fix":"ارجع لبلوك «Technological Forces» في درس ٢ («مصطلحين لا تخلطهم») والفخ اللي تحته، وبعدين كرت C6S2-c-technology.","sec":"MGT102-CH6-S2","coach":"قل له «combination» وهو يرد «technology»، وقل «outcomes of changes» وهو يرد «technological forces»، وبدّل الترتيب لين يجاوب بدون تردد."},{"id":"c6.general-def-half","ar":"تاخذ نص تعريف القوى الاجتماعية والديموغرافية","explain":"sociocultural forces لها مصدرين: social structure وnational culture، والـnational culture جزء منها مو مرادف لها. وdemographic forces تشمل changes in, or changing attitudes toward خصائص السكان، وشيخوخة السكان سببها falling birth and death rates الاثنين مع شيخوخة الـBaby Boomers.","fix":"ارجع لبلوكَي «Sociocultural Forces» و«Demographic Forces» في درس ٢ واقرأ الفخ تحت كل واحد، وبعدين كروت C6S2-c-sociocultural-forces وC6S2-c-national-culture وC6S2-c-aging-population.","sec":"MGT102-CH6-S2","coach":"اسأله: «من وين تجي sociocultural forces؟» ولازم يقول المصدرين، وبعدها «وش الكلام اللي بعد changes in في تعريف demographic؟» لين يقول or changing attitudes toward."},{"id":"c6.dereg-vs-privatize","ar":"تخلط رفع التنظيم بالخصخصة","explain":"deregulation = الحكومة تشيل قوانينها وتحكّمها عن صناعة كانت تنظّمها فيدخل منافسين جدد، أما privatization = الحكومة تبيع منظمة كانت تملكها. والاثنين أمثلة على political and legal forces مو economic.","fix":"ارجع لبلوك «Political and Legal Forces» في درس ٢ («التعريف، ورفع التنظيم ضد الخصخصة»)، وبعدين كرت C6S2-c-deregulation-privatization.","sec":"MGT102-CH6-S2","coach":"قل له «الحكومة باعت شركة الطيران الوطنية» و«الحكومة سمحت لشركات طيران جديدة تدخل السوق»، وخلّه يقول أي وحدة privatization وأي وحدة deregulation، وتحت أي قوة عامة يجون."},{"id":"c6.globalization-effects","ar":"تعكس وش تسوي العولمة وسقوط الحواجز","explain":"globalization تخلّي الدول increasingly interdependent and similar مو مستقلة أو مختلفة أكثر، ومحرّكها تدفّق capital (ولما يطلع من دولة: بطالة أعلى وركود ومعيشة أوطى) مع تراجع حواجز التجارة وحواجز المسافة والثقافة. وسقوط الحواجز يعطي المدير فرص بيع وشراء أكبر بس يخلّي شغله أصعب لأن المنافسة اشتدت، مو أسهل.","fix":"ارجع لبلوك «Globalization and the Four Forms of Capital» في درس ٣ (تعريف العولمة ووش ينتج عنها)، وبعدين بلوك «Distance, Culture, and Regional Trade Agreements» وقصة Unilever، وكروت C6S3-c-globalization وC6S3-c-distance-and-culture.","sec":"MGT102-CH6-S3","coach":"اسأله ورا بعض: «العولمة تخلّي الدول وش؟» «وش اللي سرّعها؟» «شغل المدير صار أسهل ولا أصعب وليش؟» «Unilever لما سوّت decentralization أداؤها زاد ولا نقص؟» ولا تمشّي له جواب ناقص."},{"id":"c6.capital-forms","ar":"تغلط في أشكال رأس المال الأربعة","explain":"الأشكال أربعة بس: human (تدفّق الناس بالهجرة، مو تدريب الموظفين)، financial (استثمار وقروض وaid)، resource (موارد طبيعية وقطع زي microprocessors وauto parts)، وpolitical (قوة ونفوذ يحمي الوصول للأشكال الثانية). فتضيف social أو technological capital، أو تحط مثال تحت الشكل الغلط.","fix":"ارجع لبلوك «Globalization and the Four Forms of Capital» في درس ٣ («وش يحرّك العولمة؟ رأس المال وأشكاله الأربعة») وجدوله، وبعدين كرت C6S3-c-four-forms-of-capital.","sec":"MGT102-CH6-S3","coach":"قل له أمثلة (مهندس ينتقل من الهند للرياض، قرض من بنك دولي، شحنة حديد، دبلوماسية دولة تحمي وصولها للنفط) وهو يسمّي الشكل، وبعدين يعدّ الأربعة بالإنجليزي على أصابعه."},{"id":"c6.global-vs-multidomestic","ar":"تعكس الاستراتيجية العالمية والمتعددة المحلية","explain":"global strategy = نفس المنتج الموحّد ونفس التسويق في كل دولة (ميزتها توفير التكاليف وعيبها المنافسين المحليين)، وmultidomestic = تفصيل المنتج والتسويق لكل دولة (ميزتها حصة سوقية أو سعر أعلى وعيبها تكاليف أعلى وعيب سعري). الاسم يخدعك فتعكس التعريفين أو تعكس المزايا والعيوب.","fix":"ارجع لبلوك «Global Strategy vs. Multidomestic Strategy» في درس ٣ واحفظ جدول المزايا والعيوب (Panasonic = global، Unilever = multidomestic، Kellogg's وNestlé في الهند)، وبعدين كرت C6S3-c-global-vs-multidomestic.","sec":"MGT102-CH6-S3","coach":"قل له «Rolex تبيع نفس الساعة بنفس الإعلان في كل مكان» و«Nestlé حطت نكهة marsala على Maggi في الهند»، وخلّه يسمّي الاستراتيجية، وبعدين يعطيك ميزة وعيب الثنتين بدون ما يبدّلها."},{"id":"c6.fig63-order","ar":"تغلط في ترتيب طرق التوسّع الأربع","explain":"الترتيب في Figure 6.3 من LOW لـHIGH في level of foreign involvement and investment and degree of risk: importing/exporting ← licensing/franchising ← strategic alliances/joint ventures ← wholly owned foreign subsidiary. تقرأ الشكل من اليمين، أو تقول wholly owned هي الأقل استثمار، أو تنسى إن التصدير هو الأقل تعقيداً.","fix":"ارجع لبلوك «Four Ways to Expand Internationally» في درس ٣ وارسم Figure 6.3 من راسك بالسهم (LOW يسار، HIGH يمين)، وبعدين كرت C6S3-c-four-ways-figure-6-3.","sec":"MGT102-CH6-S3","coach":"اكتب الأربع طرق على أوراق صغيرة ولخبطها، وخلّه يرتّبها من LOW لـHIGH ويقول اسم المحور كامل بالإنجليزي."},{"id":"c6.license-vs-franchise","ar":"تخلط الترخيص بالامتياز التجاري","explain":"licensing للتصنيع (الأجنبي يصنع ويوزّع) مقابل negotiated fee وخطره تسريب technological know-how، وfranchising للخدمات (حق الـbrand name وoperating know-how) مقابل lump-sum payment وshare of the profits وخطره الجودة والسمعة. وتبدّل الأطراف: licenser/franchisor هو اللي يعطي، وlicensee/franchisee هو الأجنبي اللي ياخذ.","fix":"ارجع لبلوك «Four Ways to Expand Internationally: Exporting, Importing, Licensing, and Franchising» في درس ٣ واحفظ جدول المقارنة (DuPont في الهند ضد Hilton في تشيلي)، وبعدين كرت C6S3-c-licensing-franchising.","sec":"MGT102-CH6-S3","coach":"قل له «مصنع في الهند ينتج Teflon لـDuPont مقابل رسم» و«فندق في تشيلي يشتغل باسم Hilton»، وهو يسمّي الطريقة ويقول وش المقابل ووش الخطر لكل وحدة."},{"id":"c6.alliance-jv-wholly","ar":"تخلط التحالف والمشروع المشترك والمملوكة بالكامل","explain":"كل joint venture هو strategic alliance بس مو العكس: الـJV لازم فيه new business بملكية مشتركة، والتحالف ممكن يكون عقد مكتوب بس. أما wholly owned foreign subsidiary فما فيها أي شريك محلي (independent of any local direct involvement)، والشركة تاخذ كل الأرباح وتتحمّل كل المخاطر.","fix":"ارجع لبلوك «Strategic Alliances, Joint Ventures, and Wholly Owned Foreign Subsidiaries» في درس ٣ (CPW بين General Mills وNestlé، وشركات قطع السيارات اليابانية في أمريكا)، وبعدين كروت C6S3-c-alliance-joint-venture وC6S3-c-wholly-owned-subsidiary.","sec":"MGT102-CH6-S3","coach":"اعطه ثلاث حالات: عقد تبادل خبرة بس، شركتين يأسسون شركة جديدة ٥٠-٥٠، شركة تبني مصنعها لحالها برّا؛ وهو يسمّي كل وحدة ويقول ليش مو الثانية."},{"id":"c6.tariff-trade-rules","ar":"تغلط في الرسوم الجمركية واتفاقيات التجارة","explain":"الـtariff ضريبة على imported or, occasionally, exported goods (مو المستورد بس) هدفها حماية الصناعة المحلية، وعلى المدى الطويل تقلّل التوظيف، أما free-trade doctrine = كل دولة تتخصّص في اللي تنتجه بأعلى كفاءة. وGATT انحلّت وصار مكانها WTO بسلطة عقوبات أكبر، وUruguay Round نجحت وDoha Round فشلت ٢٠١٥.","fix":"ارجع لبلوك «Declining Barriers to Trade and Investment» في درس ٣ (الـtariff، السلسلة الانتقامية، GATT وصعود التجارة الحرة) والفخ اللي تحته، وبعدين كروت C6S3-c-tariff وC6S3-c-free-trade-doctrine-gatt-wto.","sec":"MGT102-CH6-S3","coach":"اسأله: «الـtariff على وش؟» لين يقول imported وأحياناً exported، وبعدها «GATT لسه موجودة؟» و«أي جولة نجحت وأي وحدة فشلت؟» بسرعة ورا بعض."},{"id":"c6.values-vs-norms","ar":"تخلط بين القيم والمعايير","explain":"values = أفكار عن وش المجتمع يشوفه good, right, desirable, or beautiful (وش نؤمن فيه)، وnorms = unwritten, informal codes of conduct تحدد كيف تتصرف (وش نسوي). واللبنات الأساسية للثقافة اثنين بس: values وnorms، والقيم تتغيّر بس ببطء وبألم، مو ثابتة ولا سريعة.","fix":"ارجع لبلوك «National Culture and Values» في درس ٤ والفخ اللي تحته، وبعدين كروت C6S4-c-national-culture-values وC6S4-c-norms.","sec":"MGT102-CH6-S4","coach":"قل له جمل («الأمانة شي زين»، «ما تقاطع الكبير وهو يتكلم») وخلّه يقول value ولا norm، وبعدها يقول الكلمات الأربع حقّت تعريف values بالإنجليزي."},{"id":"c6.mores-vs-folkways","ar":"تخلط الأعراف الجوهرية بالأعراف اليومية","explain":"mores = norms central to the functioning of society، مخالفتها عقابها شديد وكثير منها صار قانون (القتل، السرقة، والكحول في السعودية)، وfolkways = routine social conventions of everyday life (اللبس، أدوات الأكل، الآداب) ومخالفها eccentric or ill-mannered مو شرير. والغريب ينعذر أول مرة بس لو كرّر ينلام.","fix":"ارجع لبلوك «Norms: Mores and Folkways» في درس ٤ واحفظ جدول المقارنة، وبعدين كرت C6S4-c-mores-folkways.","sec":"MGT102-CH6-S4","coach":"عدّد له تصرفات (سرقة، تلبس شورت في عرس، تاكل بدون الأدوات المناسبة، الكحول في السعودية) وهو يقول mores أو folkways ويبرّر بنوع العقوبة."},{"id":"c6.hofstede-poles-swapped","ar":"تبدّل تعريفات طرفي أبعاد هوفستيد","explain":"تحط تعريف طرف على الطرف الثاني: individualism = يُحكم عليك بإنجازك الفردي مو بخلفيتك، وcollectivism = subordination of the individual ومساهمتك في المجموعة؛ achievement = assertiveness, performance, success, competition، وnurturing = quality of life ورعاية the weak. وlong-term = thrift and persistence، وshort-term = personal stability or happiness والعيش للحاضر.","fix":"ارجع لبلوكَي «Hofstede's Model: Individualism and Power Distance» و«Hofstede's Model: The Other Three Dimensions» في درس ٤ وجدول «الأبعاد الخمسة في جدول واحد»، وبعدين كروت C6S4-c-individualism-collectivism وC6S4-c-achievement-nurturing وC6S4-c-long-short-term.","sec":"MGT102-CH6-S4","coach":"قل له كلمة مفتاحية من التعريف (thrift، quality of life، subordination، self-expression، living for the present) وهو يسمّي الطرف بالضبط والبعد اللي ينتمي له."},{"id":"c6.high-low-reversed","ar":"تعكس العالي والمنخفض في power distance وuncertainty avoidance","explain":"high power distance = المجتمع يقبل اللامساواة ويخليها تكبر، وlow = يستخدم الضرايب وبرامج الرعاية عشان يقلّلها. وuncertainty avoidance اسمه «تجنّب» بس تعريفه عن «التحمّل»، فالعالي = تحمّل أقل (صرامة وconformity ومواقف منظّمة زي اليابان وفرنسا)، والمنخفض = easygoing ويتقبّل الاختلاف (أمريكا وهونغ كونغ).","fix":"ارجع لبلوك «البعد ٢: مسافة السلطة» في مفهوم «Hofstede's Model: Individualism and Power Distance» وبلوك «البعد ٤: تجنّب عدم اليقين» في المفهوم اللي بعده بدرس ٤، وبعدين كروت C6S4-c-power-distance وC6S4-c-uncertainty-avoidance.","sec":"MGT102-CH6-S4","coach":"اوصف له مجتمع («الحكومة تاخذ ضرايب عالية وتوزّعها على المحتاجين»، «الناس يبون قانون لكل شي ويخافون من التغيير») وخلّه يقول البعد وهل هو high ولا low، وصحّحه على طول لو قلب."},{"id":"c6.country-dimension","ar":"تحط الدولة تحت البُعد الغلط","explain":"اليابان تجي في أكثر من بُعد (collectivism + achievement + high uncertainty avoidance) وأمريكا نفس الشي (individualism + low power distance + achievement + low uncertainty avoidance + short-term)، فتاخذ صفة دولة من بُعد وتحطها في بُعد ثاني. مثلاً nurturing = هولندا والسويد والدنمارك، وlong-term = تايوان وهونغ كونغ، وhigh power distance = غواتيمالا وبنما وماليزيا والفلبين.","fix":"ارجع لجدول «الأبعاد الخمسة في جدول واحد (احفظه كوحدة)» في درس ٤ وغطّ عمود الدول وسمّعها، وبعدين كرت C6S4-c-hofstede-model.","sec":"MGT102-CH6-S4","coach":"قل له اسم دولة واسم بُعد («فرنسا — uncertainty avoidance»، «اليابان — achievement ولا nurturing؟») وهو يقول الطرف، وابدأ باليابان وأمريكا لأنهم يتكررون كثير."},{"id":"c6.hofstede-vs-globe","ar":"تخلط هوفستيد بمشروع GLOBE وأرقامهم","explain":"تبدّل أرقام البحثين: Hofstede عالم نفس في IBM، 100,000+ موظف، 64 دولة، 5 أبعاد؛ وGLOBE لـRobert J. House، 17,000+ مدير، 62 دولة، 9 أبعاد. أو تنسب future أو performance orientation لـHofstede، أو تخلط institutional بـin-group collectivism (in-group = pride, loyalty, cohesiveness في المنظمة أو العائلة)، وتنسى إن power distance وuncertainty avoidance في الاثنين بتعريف مختلف.","fix":"ارجع لبلوك «Hofstede ضد GLOBE (هنا تطيح الأسئلة)» وبلوك «بطاقة المشروع» في مفهوم «The GLOBE Project» بدرس ٤، وبعدين كروت C6S4-c-globe-vs-hofstede وC6S4-c-globe-project.","sec":"MGT102-CH6-S4","coach":"قل له رقم (5، 9، 64، 62، 100,000، 17,000) وهو يقول Hofstede ولا GLOBE، وبعدها اسم بُعد (future orientation، long-term orientation، in-group collectivism، humane orientation) وهو يقول لمين."},{"id":"c6.practices-transfer","ar":"تحسب الإدارة الناجحة تنفع في كل دولة","explain":"الكتاب يقول الممارسة الفعّالة في دولة ممكن تسبّب مشاكل في ثانية، فلازم تتفصّل على الثقافة (pay-for-performance الفردي ما ينفع في اليابان الجماعية، واجتماعات يوم الجمعة لمدراء سعوديين غلط)، والثقافات still vary widely رغم العولمة. والفريق المتنوّع ثقافياً = a source of strength مو مصدر مشاكل.","fix":"ارجع لبلوك «National Culture and Global Management» في درس ٤ (قصة GE وTungsram، يوم الجمعة، مثال IBM)، وبعدين كرت C6S4-c-global-management.","sec":"MGT102-CH6-S4","coach":"اسأله: «GE نقلت أسلوبها الأمريكي للمجر، وش صار؟» وخلّه يقول مين قال lazy ومين قال pushy بدون ما يقلبهم، ويختم بالقاعدة: الممارسة لازم تتفصّل على ثقافة الدولة."}],"cases":[{"id":"C6-A","title":"Nakheel Juice: Pressure from Several Directions","text":"Nakheel Juice bottles fruit juice in Buraydah and sells it in supermarkets across Saudi Arabia. This year its managing director, Saad Al-Rashidi, faced pressure from several directions.\n\nFirst, Al-Waha Packaging, the only company in the Gulf that makes the heat-proof bottles Nakheel's filling line needs, raised its price by 30%. Nakheel has no other bottle it can use.\n\nSecond, interest rates rose across the Saudi economy, and families began spending less on extras such as juice.\n\nThird, Rimal Dairy, a large milk company that does not sell juice today, has the money and trucks to launch a juice brand whenever it chooses. Rimal's managers studied the market. They found that shoppers switch between juice brands easily. However, Nakheel fills two million bottles a day and buys its fruit concentrate from Egypt and South Africa in huge bulk orders, so its cost per bottle is far below what any newcomer would face. For now, Rimal has decided to stay out of juice."},{"id":"C6-B","title":"Bunn House Coffee: Going Abroad","text":"Bunn House is a specialty coffee chain founded in Riyadh. Two years ago it began to grow outside Saudi Arabia.\n\nIn Bahrain, Bunn House did not open any cafés itself. It sold Manama Bay Foods, a local company, the right to use the Bunn House name, recipes, and way of running cafés. Manama Bay paid a lump sum at the start and now sends Bunn House a share of its profits every year.\n\nIn Japan, Bunn House and Sakura Foods each invested money to set up a new company, Bunn House Japan, which the two firms own together.\n\nIn Egypt, Bunn House signed a written contract with Nile Roasters, a coffee company in Cairo. Bunn House brings its café know-how; Nile Roasters brings its roasting plant and its knowledge of Egyptian customers. The two firms split whatever profits or losses the new cafés make. They did not set up a new company together.\n\nIn every country, Bunn House changes its menu and its advertising to suit local tastes. This helps it win local customers, but its prices are higher than those of rivals that sell one standard menu everywhere.\n\nIn Tokyo, the Saudi operations manager introduced an 'Employee of the Month' bonus that had worked well in Riyadh. It rewarded the single best barista in each café. The Japanese staff disliked it; they felt success belonged to the whole team. When the manager switched to a team bonus, morale improved."}],"questions":[{"n":101,"lo":"LO6-1","sec":"MGT102-CH6-S1","type":"term","topic":"global-environment-definition","stem":"Which term names the whole set of global forces and conditions that operate beyond an organization's boundaries but still affect a manager's ability to acquire and utilize resources?","options":["general environment","global environment","task environment","global perspective"],"answer":1,"why":"هذا تعريف global environment في هامش الكتاب: القوى والظروف العالمية كلها برّا حدود المنظمة، بس تأثر على قدرة المدير إنه يحصّل الموارد ويستخدمها (acquire and utilize resources). الكلمة الكاشفة whole set: هي الكل، والـ task والـ general أجزاء منها.","wrong":[{"i":0,"mis":"c6.global-vs-general","note":"الكلمتين يبدون بنفس الحرف فخلطتهم؛ general environment جزء بس من البيئة العالمية، وتعريفها فيه القوى الواسعة (economic, technological…)."},{"i":2,"mis":"gen.neighbor","note":"task environment برّا المنظمة صح، بس تعريفها مربوط بالموردين والموزعين والزبائن والمنافسين، وهي جزء من البيئة العالمية (الحلقة الوسطى في Figure 6.1) مو كلها."},{"i":3,"mis":"gen.keyword","note":"كلمة global شدّتك؛ global perspective نظرة عالمية يطوّرها المدير عشان يرفع الـ efficiency والـ effectiveness، مو قوى وظروف برّا المنظمة."}],"tests":["global environment","global perspective"]},{"n":102,"lo":"LO6-1","sec":"MGT102-CH6-S1","type":"term","topic":"global-organizations","stem":"According to the book, global organizations are:","options":["only very large companies that sell their products in every country","organizations that buy inputs from overseas suppliers to lower their costs","organizations that operate and compete in more than one country","organizations that are not in a market now but could enter it if they chose"],"answer":2,"why":"التعريف: organizations that operate and compete in more than one country، يعني تشتغل وتنافس في أكثر من دولة وحدة وبس. والكتاب يقول companies large and small، فالحجم مو شرط.","wrong":[{"i":0,"mis":"gen.absolute","note":"كلمة only و every فخ؛ الكتاب يتكلم عن شركات كبيرة وصغيرة، ويكفي أكثر من دولة وحدة."},{"i":1,"mis":"gen.neighbor","note":"هذا وصف global outsourcing (تشتري مدخلاتك من موردين برّا)، مو تعريف المنظمة العالمية."},{"i":3,"mis":"gen.neighbor","note":"هذا قريب من تعريف potential competitors، ما له دخل بعدد الدول اللي تشتغل فيها المنظمة."}],"tests":["global organizations"]},{"n":103,"lo":"LO6-3","sec":"MGT102-CH6-S1","type":"term","topic":"potential-competitors","stem":"In the task environment, potential competitors are best defined as:","options":["organizations that already make goods and services similar to those of a particular organization","organizations that help another organization sell its goods or services to its customers","people and groups that may start buying from an organization at some point in the future","organizations that are outside a task environment today but could enter it if they decided to"],"answer":3,"why":"potential competitors = منظمات مو موجودة الحين في الـ task environment بس تقدر تدخل لو بغت (زي Amazon قبل ما تبيع الأثاث). الكلمة الكاشفة: outside today … could enter.","wrong":[{"i":0,"mis":"c6.competitor-vs-potential","note":"هذا تعريف competitors اللي موجودين الحين ويبيعون منتجات مشابهة؛ المحتمل لسا ما دخل."},{"i":1,"mis":"c6.task-roles-power","note":"هذا تعريف distributors اللي يساعدونك تبيع، مو منافسين أصلاً."},{"i":2,"mis":"gen.keyword","note":"كلمة potential خلتك تفكر في زبائن المستقبل، بس المصطلح عن منافسين ممكن يدخلون، مو زبائن."}],"tests":["potential competitors","competitors"]},{"n":104,"lo":"LO6-3","sec":"MGT102-CH6-S1","type":"term","topic":"brand-loyalty","stem":"Which of the following is the book's definition of brand loyalty?","options":["Customers' preference for the products of organizations currently existing in the task environment","Customers' preference for the products of new organizations that have just entered the task environment","Cost advantages that established organizations gain from very large operations","Government policies that create barriers to entry and limit imports by overseas companies"],"answer":0,"why":"brand loyalty = تفضيل الزبائن لمنتجات الشركات الموجودة حالياً في السوق (currently existing). وعشان كذا هي حاجز دخول: الجديد لازم يصرف تكاليف تسويق ضخمة عشان ياخذ حصة.","wrong":[{"i":1,"mis":"gen.reversed","note":"قلبت الاتجاه؛ الولاء يكون للشركات القائمة، والداخل الجديد هو اللي يتعب منه."},{"i":2,"mis":"c6.barrier-sources","note":"هذا تعريف economies of scale (مزايا تكلفة من الحجم الكبير)، مصدر ثاني من مصادر الحواجز."},{"i":3,"mis":"c6.barrier-sources","note":"هذا وصف administrative barriers (زي قيود اليابان على استيراد الرز، قفلت السوق لين 1993)، وهي تابعة لـ government regulations مو للولاء."}],"tests":["brand loyalty","administrative barriers"]},{"n":105,"lo":"LO6-1","sec":"MGT102-CH6-S1","type":"concept","topic":"opportunities-vs-threats","stem":"According to the book, which of the following is an OPPORTUNITY in the global environment rather than a threat?","options":["the rise of new global competitors","a global economic recession","the opening of new global markets","a worldwide shortage of oil"],"answer":2,"why":"الكتاب يعطي ثلاث فرص: efficient new production technology و lower-cost components و opening of new global markets، وكلها تخليك تصنع وتبيع أكثر وتقوّي منظمتك. والخيارات الثلاثة الباقية هي بالضبط أمثلة الكتاب على التهديد. ومن الفرص كمان إن منتجات زي Coca-Cola و iPads صارت مقبولة عند زبائن العالم كله.","wrong":[{"i":0,"mis":"gen.reversed","note":"rise of new global competitors من أمثلة التهديد في الكتاب؛ منافس جديد ياخذ من زبائنك، مو فرصة."},{"i":1,"mis":"gen.reversed","note":"الركود الاقتصادي العالمي تهديد ممكن يدمّر (devastate) المنظمة لو ما قدرت تبيع."},{"i":3,"mis":"gen.reversed","note":"oil shortage ثالث تهديد في قائمة الكتاب؛ يمكن حسبته فرصة لأن الأسعار ترتفع، بس الكتاب يحطه تهديد."}],"tests":["opportunities and threats","global environment"]},{"n":106,"lo":"LO6-3","sec":"MGT102-CH6-S1","type":"concept","topic":"global-outsourcing-risks","stem":"According to the book, which statement about global outsourcing is true?","options":["It means that a company makes its products at home and then sells those products in other countries.","After the pandemic's supply-chain delays, most companies moved even more of their jobs overseas.","Boeing outsourced more parts for the 787 Dreamliner than for the 777, and the 787 was delayed for years.","Companies hire overseas intermediaries because these brokers are located close to the companies' own customers."],"answer":2,"why":"الكتاب يقول Boeing 777 نجحت بمكونات من أكثر من 500 مورّد عالمي، فانبسطت Boeing وزادت الـ outsourcing في 787 Dreamliner، بس مشاكل كثيرة أخّرت الطيارة سنين. يعني الـ outsourcing له وجهين: يخفّض التكلفة بس فيه مخاطر.","wrong":[{"i":0,"mis":"c6.outsourcing-vs-exporting","note":"هذا تعريف exporting (تصنع في بلدك وتبيع برّا)؛ global outsourcing إنك تشتري أو تنتج المدخلات أو المنتج النهائي من موردين برّا عشان تخفض التكلفة."},{"i":1,"mis":"gen.reversed","note":"قلبت الاتجاه؛ بعد تأخيرات الجائحة بعض الشركات بدأت ترجّع الوظائف لبلدها (reshoring)، وتقرير Deloitte يقول أكثر من 60% من التنفيذيين يتوقعونه."},{"i":3,"mis":"gen.detail","note":"الوسطاء (intermediaries or brokers) زي Li & Fung قريبين من الموردين المحتملين مو من الزبائن، وشغلهم يدوّرون للشركة أنسب مورّد."}],"tests":["global outsourcing","outsourcing risks","reshoring","intermediaries","global supply chain"]},{"n":107,"lo":"LO6-3","sec":"MGT102-CH6-S1","type":"concept","topic":"new-entrants-and-rivalry","stem":"Which statement about competition in the task environment is true according to the book?","options":["When new competitors enter an industry, competition increases and prices and profits go down.","The higher the barriers to entry, the more competitors an organization faces in its task environment.","Low rivalry among competitors creates a highly threatening task environment for managers.","Administrative barriers, such as Japan's old limits on rice imports, make it easier for overseas firms to sell."],"answer":0,"why":"الكتاب يقول لما يدخلون منافسين جدد الصناعة، المنافسة تزيد والأسعار والأرباح تنقص، زي Best Buy مع Amazon. ومع منافسين أقل يصير أسهل تجيب زبائن وتخلي أسعارك عالية. ونفس الفكرة في rivalry: التنافس العالي عادةً يجيب price competition والأسعار الطايحة تقلّل الأرباح.","wrong":[{"i":1,"mis":"c6.barriers-reversed","note":"قلبت العلاقة؛ كل ما ارتفعت الحواجز قلّ عدد المنافسين وقلّ تهديد المنافسة."},{"i":2,"mis":"gen.reversed","note":"قلبت الاثنين؛ intense rivalry هو اللي يخلي البيئة عالية التهديد، والتنافس المنخفض يخلي الضغط معتدل ويعطيك فرص أكبر تحصّل الموارد."},{"i":3,"mis":"gen.reversed","note":"administrative barriers سياسات حكومية تحطّ حواجز وتحدّ الاستيراد، زي اليابان اللي قفلت سوق الرز لين 1993 وبعدها سمحت بـ 8% بس."}],"tests":["new entrants","potential competitors","rivalry","price competition","barriers to entry","administrative barriers"]},{"n":108,"lo":"LO6-3","sec":"MGT102-CH6-S1","type":"scenario","topic":"supplier-bargaining-power","stem":"A juice factory in Jeddah needs a special preservative that only one company makes, because that company holds the patent. The factory cannot make its drinks without it, and the maker has just doubled its price. Which change would most weaken the preservative maker's bargaining position?","options":["The factory launches several new drinks that all depend on this same preservative.","The patent expires, and several other firms start making a similar preservative.","The factory signs with a large distributor that controls access to many shoppers.","The preservative maker builds its own factories abroad to protect its technology."],"answer":1,"why":"قوة المورّد تجي من شرطين مع بعض: sole source (المصدر الوحيد) و vital input (مدخل حيوي). لما تنتهي البراءة ويطلعون موردين بدائل يطيح الشرط الأول، والمنظمة اللي عندها موردين كثار هي اللي تصير قوية، نفس NutraSweet لما انتهت براءتها بعد 17 سنة وطاح سعرها.","wrong":[{"i":0,"mis":"gen.reversed","note":"هذا يقوّي المورّد مو يضعفه؛ كل ما زاد اعتمادك على المدخل، قوي موقف المورّد أكثر."},{"i":2,"mis":"c6.task-roles-power","note":"الموزّع يساعدك تبيع للزبائن، وما يغيّر شي في علاقتك بمورّد المادة الحافظة."},{"i":3,"mis":"gen.neighbor","note":"حماية proprietary technology تخلي المورّد يحتفظ بسرّه، يعني يبقى المصدر الوحيد وقوته ما تنقص."}],"tests":["suppliers","bargaining position","alternative suppliers","proprietary technology"]},{"n":109,"lo":"LO6-3","sec":"MGT102-CH6-S1","type":"scenario","topic":"distributor-power","stem":"A huge online marketplace controls access to millions of shoppers in Saudi Arabia. It tells a small date company in Madinah: 'Cut your prices, or we will sell only your rivals' dates.' In the book's terms, what is the date company facing?","options":["a supplier that is strong because it is the sole source of a vital input","a distributor that is strong because it controls customers' access to its goods","a potential competitor that has the resources to enter the dates market","an economic force from the general environment, such as rising interest rates"],"answer":1,"why":"الموزّع يساعدك تبيع للزبائن، ولو كبر لدرجة إنه يتحكم في وصولهم لبضاعتك يقدر يطالبك تخفض أسعارك، نفس Walmart مع P&G. السوق الإلكتروني هنا يبيع تمر الشركة للمتسوقين، يعني موزّع. ولو غيّرت الشركة طريقة توزيعها، زي إنها تبيع مباشرة أونلاين، ممكن يتغير ميزان القوة.","wrong":[{"i":0,"mis":"c6.task-roles-power","note":"المورّد يعطيك مدخلات زي المواد الخام؛ السوق الإلكتروني ما يعطي الشركة شي، هو يبيع عنها."},{"i":2,"mis":"c6.competitor-vs-potential","note":"ما قال إنه بيبيع تمر خاص فيه؛ الضغط جاي من تحكمه في الزبائن، مو من دخوله السوق."},{"i":3,"mis":"c6.task-vs-general","note":"هذي قوة مباشرة من شركة تتعامل معها يومياً = task environment، مو قوة عامة زي أسعار الفائدة."}],"tests":["distributors","distribution methods"]},{"n":110,"lo":"LO6-3","sec":"MGT102-CH6-S1","type":"scenario","topic":"economies-of-scale","stem":"A new coffee roaster in Madinah wants to compete with a huge national roaster. The national firm roasts beans in very large quantities and buys its inputs in bulk, so its cost per kilo is far lower than any newcomer could reach. Which source of barriers to entry is protecting the national firm?","options":["brand loyalty","government regulations","economies of scale","global outsourcing"],"answer":2,"why":"economies of scale = cost advantages associated with large operations. الشركة الكبيرة تنتج بكميات ضخمة وتشتري بالجملة (in bulk)، فتكلفتها أقل من أي داخل جديد، ودخول السوق يصير مكلف عليه.","wrong":[{"i":0,"mis":"c6.barrier-sources","note":"brand loyalty يعني الزبائن يفضّلون منتجات الشركة القائمة، والقصة ما ذكرت الزبائن أبد، ذكرت التكلفة."},{"i":1,"mis":"c6.barrier-sources","note":"ما فيه أي قانون أو قرار حكومي يمنع الدخول في القصة."},{"i":3,"mis":"gen.keyword","note":"خفض التكلفة خلاك تفكر في outsourcing، بس الشركة ما تعاقدت مع موردين برّا؛ ميزتها من حجمها."}],"tests":["economies of scale","barriers to entry","government regulations"]},{"n":111,"lo":"LO6-3","sec":"MGT102-CH6-S1","type":"scenario","topic":"customers-responsiveness","stem":"A private clinic in Riyadh finds that many of its patients now want to book visits through an app and come in the evening. Its managers quickly build their own app and add evening hours to satisfy these patients. Which task environment force is the clinic responding to?","options":["distributors, who help the clinic sell its services","suppliers, who provide the clinic with input resources","competitors, who try to attract the same patients","customers, whose changing needs the clinic must satisfy"],"answer":3,"why":"المرضى هنا هم customers، الأفراد اللي يشترون خدمات العيادة، واحتياجاتهم تغيّرت. الكتاب يقول نجاح المنظمة يعتمد على responsiveness to customers، يعني تقدر تلبي احتياجاتهم ولا لا. وعشان كذا المدير لازم يعرف مجموعات زبائنه الرئيسية، زي Dell اللي تقسّم زبائنها لأربع مجموعات.","wrong":[{"i":0,"mis":"c6.task-roles-power","note":"العيادة سوّت التطبيق بنفسها، وما فيه منظمة ثانية تبيع عنها، فما فيه distributor هنا."},{"i":1,"mis":"c6.task-roles-power","note":"الموردين يعطون العيادة مدخلات (أجهزة، أدوية، موظفين)؛ القصة عن طلبات المرضى مو عن المدخلات."},{"i":2,"mis":"gen.neighbor","note":"ما فيه أي عيادة منافسة في القصة؛ التغيير جاي من احتياجات المرضى نفسهم."}],"tests":["customers","responsiveness to customers"]},{"n":112,"lo":"LO6-2","sec":"MGT102-CH6-S1","type":"figure","topic":"figure-6-1-task-forces","stem":"Look at Figure 6.1. Which group contains ONLY forces from the task environment?","img":"img/mgt102/figure-6-1.png","options":["Suppliers, Distributors, Economic forces","Customers, Competitors, Demographic forces","Suppliers, Customers, Competitors","Distributors, Customers, Technological forces"],"answer":2,"why":"الحلقة الوسطى (TASK ENVIRONMENT) فيها أربع بس: Competitors فوق، Distributors يمين، Customers تحت، Suppliers يسار. أي شي بعده كلمة forces في الحلقة الخارجية = general environment.","wrong":[{"i":0,"mis":"c6.task-vs-general","note":"Economic forces على يسار الحلقة الخارجية، يعني general مو task."},{"i":1,"mis":"c6.task-vs-general","note":"Demographic forces تحت يمين في الحلقة الخارجية، يعني general."},{"i":3,"mis":"c6.task-vs-general","note":"Technological forces فوق في الحلقة الخارجية، من القوى العامة مو القريبة."}],"tests":["task environment","general environment"]},{"n":113,"lo":"LO6-3","sec":"MGT102-CH6-S1","type":"figure","topic":"figure-6-2-barriers-effect","stem":"Look at Figure 6.2. What effect do the barriers to entry created by the three boxes on the left have?","img":"img/mgt102/figure-6-2.png","options":["They push current competitors out of the industry.","They attract potential competitors into the industry.","They create economies of scale and brand loyalty.","They deter potential competitors from entering."],"answer":3,"why":"اقرأ الشكل من اليسار لليمين: الصناديق الثلاثة ← create barriers to entry ← that deter potential competitors. يعني الحواجز تردع المنافسين المحتملين اللي لسا برّا السوق.","wrong":[{"i":0,"mis":"c6.competitor-vs-potential","note":"الشكل يقول potential competitors، مو المنافسين الموجودين الحين في السوق."},{"i":1,"mis":"c6.barriers-reversed","note":"قلبت الأثر؛ الحواجز تصعّب الدخول وتردع، ما تجذب أحد."},{"i":2,"mis":"c6.barrier-sources","note":"قلبت اتجاه الأسهم؛ economies of scale و brand loyalty هي المصادر اللي تصنع الحواجز، مو نتيجتها."}],"tests":["barriers to entry","potential competitors"]},{"n":114,"lo":"LO6-3","sec":"MGT102-CH6-S1","type":"list","topic":"global-supply-chain-threats","stem":"According to the book, managing a global supply chain brings one opportunity and two threats. Which pair names the two THREATS?","options":["poor-quality parts that hurt the brand, and poor treatment of workers that hurts the company's reputation","poor-quality parts that hurt the brand, and gaining access to low-cost products that are made abroad","poor treatment of workers that hurts the company's reputation, and large distributors that demand lower prices","poor-quality parts that hurt the brand, and new competitors that enter the industry and push prices down"],"answer":0,"why":"الكتاب يقول: الفرصة = منتجات رخيصة من برّا تخفّض تكلفة المدخلات، والتهديدين: (1) سيطرة أقل على مقاولين بعيدين، فلو سلّموا جودة رديئة تتضرر الـ brand، و(2) social responsibility: لو الموردين ما يعاملون عمالهم بأخلاق تتضرر سمعة الشركة. وعشان كذا Levi Strauss سوّت Terms of Engagement وبعدها Worker Well-Being لموردينها.","wrong":[{"i":1,"mis":"gen.reversed","note":"الوصول لمنتجات رخيصة من برّا هو الفرصة الوحيدة في القائمة، مو تهديد."},{"i":2,"mis":"gen.neighbor","note":"الموزّع اللي يطالب بأسعار أقل تهديد جاي من الـ distributors، مو من سلسلة التوريد العالمية."},{"i":3,"mis":"gen.neighbor","note":"دخول منافسين جدد تهديد جاي من الـ competitors، مو من إدارة الموردين برّا."}],"tests":["global supply chain","opportunities and threats","social responsibility","global outsourcing"]},{"n":115,"lo":"LO6-3","sec":"MGT102-CH6-S1","type":"list","topic":"kinds-of-suppliers","stem":"Suppliers provide an organization with the input resources it needs. Which of the following would NOT be counted as a supplier to a manufacturing company?","options":["a bank that provides the company with capital","a trade union that can control the supply of labor","a delivery firm that ships its finished goods to buyers","a university that trains the skilled workers it will hire"],"answer":2,"why":"المورّد يعطيك input resources: مواد وقطع وحتى موظفين ورأس مال، فالبنك (capital) والنقابة والجامعة (labor) كلهم suppliers. شركة التوصيل اللي تشحن منتجك الجاهز للزبائن تساعدك تبيع، فهي distributor زي FedEx و UPS.","wrong":[{"i":0,"mis":"gen.partial","note":"حسبت المورّد يعطي مواد خام بس؛ الكتاب يعدّ البنوك ومزوّدي رأس المال من key suppliers."},{"i":1,"mis":"gen.partial","note":"النقابة مورّد عمالة: تتحكم في عرض العمالة بحق الإضراب، فهي من الـ suppliers."},{"i":3,"mis":"gen.partial","note":"الجامعات والمؤسسات التعليمية تدرّب موظفين المستقبل، فالكتاب يعدّها suppliers of labor."}],"tests":["suppliers","trade unions","distributors"]},{"n":116,"lo":"LO6-2","sec":"MGT102-CH6-S1","type":"tf","topic":"task-vs-general-effect","stem":"According to the book, task-environment forces have a big impact on managers' short-term decisions, while general-environment forces affect only the organization itself and leave its task environment untouched.","options":["True","False"],"answer":1,"why":"غلط في نصها الثاني. أول جزء صح: الموردين والموزعين والزبائن والمنافسين يأثرون على قدرة المدير يحصّل الموارد ويصرّف المخرجات يومياً وأسبوعياً وشهرياً، فلهم أثر كبير على short-term decision making. بس تعريف general environment يقول القوى تأثر على المنظمة and its task environment، يعني تحرّك الـ task environment نفسها.","wrong":[{"i":0,"mis":"gen.partial","note":"صدّقت الجملة لأن أولها صح؛ بس تعريف general environment فيه and its task environment، وكلمة only قلبت المعنى."}],"tests":["task environment","general environment","short-term decision making"]},{"n":117,"lo":"LO6-3","sec":"MGT102-CH6-S1","type":"vocab","topic":"vocab-sole","stem":"In the sentence 'After his partner left the business, Khalid became the sole owner of the café, so every decision is now his alone,' the word 'sole' most nearly means:","options":["main","only","former","foreign"],"answer":1,"why":"sole = الوحيد، ما فيه غيره أبد. والكلمة الكاشفة his alone: خالد صار المالك الوحيد بعد ما طلع شريكه.","wrong":[{"i":0,"mis":"gen.vocab","note":"main يعني الرئيسي، ويمكن فيه ملاك ثانيين معه؛ sole يعني ما فيه أحد ثاني أبد."},{"i":2,"mis":"gen.vocab","note":"former يعني السابق، وخالد صار المالك الحين مو قبل."},{"i":3,"mis":"gen.vocab","note":"foreign يعني أجنبي، والجملة ما تتكلم عن جنسية المالك."}],"tests":["sole"]},{"n":118,"lo":"LO6-3","sec":"MGT102-CH6-S1","type":"vocab","topic":"vocab-deter","stem":"In the sentence 'High delivery fees may deter many customers from ordering food online,' the word 'deter' most nearly means:","options":["attract","support","discourage","identify"],"answer":2,"why":"deter = يردع ويخلي الشخص يتراجع عن الشي. رسوم التوصيل العالية تخلي الزبائن يتراجعون وما يطلبون.","wrong":[{"i":0,"mis":"gen.vocab","note":"attract العكس: يجذب، والرسوم العالية ما تجذب أحد يطلب."},{"i":1,"mis":"gen.vocab","note":"support يعني يدعم ويساعد، والرسوم العالية ما تساعد الزبون يطلب."},{"i":3,"mis":"gen.vocab","note":"identify يعني يحدد أو يتعرّف على، ما فيها معنى المنع."}],"tests":["deter"]},{"n":119,"lo":"LO6-1","sec":"MGT102-CH6-S1","type":"vocab","topic":"vocab-scarce","stem":"What does the word 'scarce' mean?","options":["ثمين وغالي","نادر وقليل","كثير ومتوفّر","مخيف ومقلق"],"answer":1,"why":"scarce = نادر وقليل وما يكفي الكل، وعشان كذا الشركات تتسابق عليه. في الكتاب: المدراء يتنافسون على scarce and valuable resources.","wrong":[{"i":0,"mis":"gen.vocab","note":"ثمين = valuable، الكلمة اللي تجي جنبها في الجملة، بس مو نفس المعنى."},{"i":2,"mis":"gen.vocab","note":"هذا العكس تماماً؛ scarce يعني ما يكفي الكل."},{"i":3,"mis":"gen.vocab","note":"شكلها قريب من scare (يخوّف)، بس scarce معناها قليل."}],"tests":["scarce"]},{"n":120,"lo":"LO6-3","sec":"MGT102-CH6-S1","type":"vocab","topic":"vocab-impede","stem":"What does the word 'impede' mean?","options":["يسهّل ويساعد","يفرض ويلزم","يعيق ويعرقل","يستورد ويجلب"],"answer":2,"why":"impede = يعيق ويوقف في طريقك. الكتاب: government regulations that impede entry، يعني لوائح حكومية تعيق دخول شركات جديدة.","wrong":[{"i":0,"mis":"gen.vocab","note":"يسهّل هو العكس؛ اللوائح اللي impede entry تصعّب الدخول مو تسهّله."},{"i":1,"mis":"gen.vocab","note":"يفرض = impose، شكلها قريب بس المعنى غير."},{"i":3,"mis":"gen.vocab","note":"يستورد = import، تبدأ بنفس الحرفين بس ما لها علاقة."}],"tests":["impede"]},{"n":201,"lo":"LO6-2","sec":"MGT102-CH6-S2","type":"term","topic":"general-environment-definition","stem":"The wide set of economic, technological, social, demographic, political, and legal forces that influence both an organization and the groups it deals with directly is called the:","options":["global environment","general environment","task environment","process of globalization"],"answer":1,"why":"general environment هي القوى الواسعة (اقتصادية، تقنية، اجتماعية-ثقافية، ديموغرافية، سياسية وقانونية) اللي تأثر على المنظمة وعلى الـ task environment حقتها. المفتاح في آخر السؤال: تأثر على المنظمة وعلى المجموعات اللي تتعامل معها مباشرة، يعني هي الدائرة الأوسع اللي تحيط بالـ task environment.","wrong":[{"i":0,"mis":"c6.global-vs-general","note":"الاسمين متشابهين، بس global environment هي الكل (task + general)، والسؤال عن الجزء الواسع اللي يأثر على المجموعات اللي تتعامل معها المنظمة."},{"i":2,"mis":"c6.task-vs-general","note":"الـ task environment هي المجموعات نفسها (المورّدين والموزّعين والزبائن والمنافسين)، مو القوى الاقتصادية والسياسية اللي تأثر عليهم."},{"i":3,"mis":"gen.neighbor","note":"العولمة فيها economic وpolitical وsocial بعد، بس هي القوى اللي تربط أنظمة الدول ببعض (درس 3)، مو اسم الدائرة الواسعة."}],"tests":["general environment","global environment","task environment"]},{"n":202,"lo":"LO6-3","sec":"MGT102-CH6-S2","type":"term","topic":"technological-forces-definition","stem":"Which option best describes technological forces, according to the textbook?","options":["the combination of skills and equipment that managers use to design, produce, and distribute goods and services","the results of changes in the laws and regulations that control how goods and services are designed and made","the results of changes in the tools and skills that managers use to design, make, and deliver goods and services","the pressures from a society's values and norms that shape which goods and services people are willing to accept"],"answer":2,"why":"technological forces = نتايج التغيّرات (outcomes of changes) في التقنية اللي يستخدمها المدير في التصميم والإنتاج والتوزيع. الكلمة اللي تفضحها: نتايج التغيّر في الأدوات والمهارات، أما المزيج نفسه (skills and equipment) فهو technology.","wrong":[{"i":0,"mis":"c6.tech-vs-tech-forces","note":"هذا تعريف technology (المزيج نفسه)، والسؤال عن نتايج التغيّر فيها، وهذا أشهر فخ في هالقوة."},{"i":1,"mis":"c6.general-force-mixup","note":"نتايج التغيّر في القوانين واللوائح هي political and legal forces، حتى لو كان الكلام عن الإنتاج."},{"i":3,"mis":"c6.general-force-mixup","note":"قيم المجتمع ومعاييره تتبع sociocultural forces (national culture)، مو القوى التقنية."}],"tests":["technological forces","technology"]},{"n":203,"lo":"LO6-3","sec":"MGT102-CH6-S2","type":"term","topic":"sociocultural-forces-sources","stem":"According to the textbook, sociocultural forces are pressures that come from:","options":["the traditional system of relationships between people and groups, and the values and approved norms of behavior in a society","the values and approved norms of behavior in a society, and changing attitudes toward the age and gender of its people","the traditional system of relationships between people and groups, and changes in the laws and regulations of a nation","changes in the age, gender, and race of a population, and changes in the technology used to make goods and services"],"answer":0,"why":"sociocultural forces لها مصدرين: social structure (النظام التقليدي للعلاقات بين الناس والمجموعات) وnational culture (القيم اللي المجتمع يشوفها مهمة ومعايير السلوك اللي يقبلها أو يعاقب عليها). الخيار الصح يوصف الاثنين بتعريفهم بدون ما يذكر اسمهم، فلازم تعرف التعريفين.","wrong":[{"i":1,"mis":"c6.general-def-half","note":"أخذت نص صح بس (القيم والمعايير = national culture)، والنص الثاني تغيّر المواقف تجاه العمر والجنس وهذا demographic forces مو social structure."},{"i":2,"mis":"c6.general-force-mixup","note":"النص الأول صح (social structure)، بس تغيّر القوانين واللوائح هو political and legal forces مو national culture."},{"i":3,"mis":"gen.neighbor","note":"هذي قوتين جيران: تغيّر خصائص السكان demographic، وتغيّر التقنية technological، وما فيها ولا مصدر من مصادر sociocultural."}],"tests":["sociocultural forces","social structure","national culture"]},{"n":204,"lo":"LO6-3","sec":"MGT102-CH6-S2","type":"term","topic":"demographic-forces-definition","stem":"Which of the following is the textbook's definition of demographic forces?","options":["Outcomes of changes in, or changing attitudes toward, the characteristics of a population, such as age, gender, and race","Outcomes of changes in the characteristics of a population, such as age, gender, and race, but not in attitudes toward them","The set of values that a society considers important and the norms of behavior that it approves or sanctions","Interest rates, unemployment, economic growth, and other factors that affect the general health of a population"],"answer":0,"why":"التعريف له جزئين: changes in (تغيّر الخصائص نفسها) أو changing attitudes toward (تغيّر نظرة الناس لها)، زي العمر والجنس والعِرق. الخيار اللي فيه الجزئين مع بعض هو الصح.","wrong":[{"i":1,"mis":"c6.general-def-half","note":"هذا نص التعريف بس؛ الكتاب يقول حتى تغيّر المواقف تجاه الخصائص (changing attitudes toward) يُحسب قوة ديموغرافية."},{"i":2,"mis":"gen.neighbor","note":"هذا تعريف national culture (قيم ومعايير)، وهي مصدر من مصادر sociocultural forces مو demographic."},{"i":3,"mis":"gen.keyword","note":"كلمة population سحبتك، بس أسعار الفائدة والبطالة والنمو الاقتصادي هي economic forces."}],"tests":["demographic forces","national culture","economic forces"]},{"n":205,"lo":"LO6-2","sec":"MGT102-CH6-S2","type":"concept","topic":"continuous-analysis-general-environment","stem":"According to the textbook, why must managers keep analyzing forces in the general environment all the time?","options":["These forces pressure managers every day and mainly shape their short-term decision making.","These forces affect ongoing planning and decision making, often in ways that managers may not notice.","These forces affect the organization directly but have no effect on its suppliers, distributors, or customers.","Changes in these forces are easier to spot and respond to than events in the task environment."],"answer":1,"why":"الكتاب يقول القوى العامة تأثر على التخطيط والقرارات المستمرة (ongoing decision making and planning)، وكثير مرات لها آثار على الـ task environment المدير ما يكون واعي لها (may not be aware of)، زي أزمة 2007–2008. عشان كذا لازم يحللها باستمرار، وكل ما كان أسرع كل ما ردّت المنظمة أسرع.","wrong":[{"i":0,"mis":"c6.task-vs-general","note":"قلبت الصفات: الضغط اليومي والقرارات قصيرة المدى صفات الـ task environment، أما العامة فتأثر على التخطيط والقرارات المستمرة."},{"i":2,"mis":"gen.partial","note":"أخذت نص التعريف: الـ general environment تأثر على المنظمة وعلى الـ task environment كمان، يعني المورّدين والزبائن يتأثرون."},{"i":3,"mis":"gen.reversed","note":"العكس: الكتاب يقول تغيّرات البيئة العامة غالباً أصعب في التحديد والرد (more difficult) من أحداث الـ task environment، وهذا سبب زيادة إنك تراقبها دايم."}],"tests":["general environment","task environment","ongoing decision making and planning","effects managers may not be aware of","short-term decision making"]},{"n":206,"lo":"LO6-3","sec":"MGT102-CH6-S2","type":"concept","topic":"economic-forces-components","stem":"Which statement about economic forces is TRUE according to the textbook?","options":["They include interest rates, inflation, unemployment, and economic growth, and they can create both opportunities and threats for managers.","They include interest rates, inflation, and unemployment, and good economic times make resources harder and more costly to acquire.","They include interest rates, inflation, and the aging of the population, which together shape the general health of an economy.","They mainly hurt profit-seeking firms such as hotels and retail stores, while nonprofits such as charities keep their donations steady."],"answer":0,"why":"economic forces = interest rates وinflation وunemployment وeconomic growth (أربعة)، وغيرها من العوامل اللي تأثر على صحة اقتصاد الدولة أو المنطقة. والكتاب يقول تعطي فرص وتهديدات مع بعض: بطالة منخفضة وفوائد نازلة = الناس تصرف أكثر والمنظمات تبيع أكثر، والاقتصاد السيئ يصعّب الحصول على الموارد.","wrong":[{"i":1,"mis":"gen.reversed","note":"قلبتها: الأوقات الاقتصادية الزينة تخلّي الموارد أسهل وأرخص (easier or more inexpensive) والمنظمات تزدهر، مو أصعب وأغلى."},{"i":2,"mis":"c6.general-force-mixup","note":"شيخوخة السكان (aging of the population) تتبع demographic forces، والعنصر الرابع في التعريف economic growth مو العمر."},{"i":3,"mis":"gen.partial","note":"الفنادق انضربت صح (إشغالها طاح أكثر من 70%)، بس الجمعيات الخيرية والجامعات بعد نقصت تبرعاتها بنسب من خانتين."}],"tests":["economic forces","interest rates","inflation","unemployment","economic growth","aging of the population"]},{"n":207,"lo":"LO6-3","sec":"MGT102-CH6-S2","type":"concept","topic":"technological-forces-effects","stem":"Which statement about technological forces is TRUE according to the textbook?","options":["The pace of technological change has slowed in recent decades as computer hardware and software matured.","Technological change mostly threatens organizations and rarely creates chances for new goods and services.","Telecommuting, videoconferencing, and cloud computing changed employees' work, but not the manager's own job.","Technological change can make established products obsolete, forcing managers to find new ways to satisfy customer needs."],"answer":3,"why":"الكتاب يقول التغيّر التقني يخلّي منتجات قائمة obsolete (انتهى زمنها)، زي شاشات CRT والموسوعات المجلّدة والصحف والمجلات، فيضطر المدير يدوّر طرق جديدة يرضي فيها الزبون. وبنفس الوقت يفتح فرص لمنتجات جديدة.","wrong":[{"i":0,"mis":"gen.reversed","note":"بالعكس، الكتاب يقول وتيرة التغيّر التقني تسارعت بقوة (accelerated greatly) بسبب المعالجات وأجهزة الكمبيوتر وبرامجه، وآثارها لسه تكبر."},{"i":1,"mis":"c6.one-sided-forces","note":"التقنية تهدد صح، بس الكتاب يقول كمان تخلق a host of new opportunities، زي معالجات AMD Ryzen."},{"i":2,"mis":"gen.partial","note":"أخذت نص الفكرة: الكتاب يقول التقنية غيّرت طبيعة الشغل including the manager's job، فالمدير صار يشرف على موظفين موزّعين جغرافياً."}],"tests":["technological forces","obsolete products","telecommuting","videoconferencing","cloud computing"]},{"n":208,"lo":"LO6-3","sec":"MGT102-CH6-S2","type":"concept","topic":"sociocultural-forces-national-culture","stem":"Which statement about sociocultural forces is accurate according to the textbook?","options":["Social stratification is high in New Zealand and the United States, where top managers come mainly from the upper classes.","In the United States individualism is highly valued, while in Korea and Japan individuals are expected to conform to the group.","Social structure and national culture differ from one society to another, but they stay fixed within a society over time.","Pressures from social structure and national culture can only constrain the way organizations operate and managers behave."],"answer":1,"why":"الكتاب يعطي هالمثال على اختلاف national culture بين المجتمعات: في أمريكا الفردانية (individualism) مقدَّرة بقوة، وفي كوريا واليابان المتوقع من الفرد يمشي مع توقعات الجماعة (conform). وهالاختلافات تحدد كيف المدير يحفّز موظفينه ويقودهم.","wrong":[{"i":0,"mis":"gen.reversed","note":"قلبتها: نيوزيلندا وأمريكا تدرّجها الاجتماعي منخفض وكبار مدراء أمريكا من كل الطبقات، والعالي زي الهند والتبت وبريطانيا وفرنسا."},{"i":2,"mis":"gen.partial","note":"نصها صح (تختلف بين المجتمعات)، بس الكتاب يقول تتغيّر كمان داخل المجتمع مع الوقت، زي إن ناس كثير في آسيا (هونغ كونغ، سنغافورة، كوريا، الصين) يشوفون إن الجيل الأصغر أكثر فردانية، أو أوروبا الشرقية اللي قيم الفردانية وريادة الأعمال فيها تحل محل الجماعية."},{"i":3,"mis":"c6.one-sided-forces","note":"كلمة only هي الفخ؛ الكتاب يقول الضغوط ممكن تقيّد أو تسهّل (constrain or facilitate)."}],"tests":["sociocultural forces","national culture","individualism","social structure","social stratification"]},{"n":209,"lo":"LO6-3","sec":"MGT102-CH6-S2","type":"concept","topic":"political-legal-forces-examples","stem":"Which statement about political and legal forces is TRUE according to the textbook?","options":["Falling legal trade barriers give companies chances to sell goods abroad, and they also lower the level of competition in the task environment.","The European Commission reviewed Apple's purchase of Shazam and blocked it, saying the deal broke the European Union's antitrust laws.","Brexit is an example of political integration, because the UK economy became more open and more global after it left the European Union.","They are outcomes of changes in laws and regulations, such as a growing emphasis on environmental protection, workplace safety, and limits on discrimination."],"answer":3,"why":"political and legal forces = نتايج التغيّرات في القوانين واللوائح. أمثلة التعريف: deregulation وprivatization وزيادة التركيز على حماية البيئة، والكتاب يزيد عليها: حماية الأنواع المهددة بالانقراض، وسلامة مكان العمل (workplace safety)، والقيود القانونية ضد التمييز بسبب العِرق أو الجنس أو العمر.","wrong":[{"i":0,"mis":"c6.one-sided-forces","note":"نص الجملة صح (فرصة تبيع برّا)، بس سقوط الحواجز كمان تهديد لأنه يدخّل شركات أجنبية سوقك ويزيد المنافسة في الـ task environment، مو يقللها."},{"i":1,"mis":"gen.reversed","note":"العكس: المفوضية الأوروبية راجعت الصفقة وعطت Apple الضوء الأخضر، وقالت إنها ما تخالف antitrust laws."},{"i":2,"mis":"gen.reversed","note":"Brexit خروج من اتحاد، يعني عكس الـ political integration، والكتاب يقول اقتصاد بريطانيا صار يبان أقل انفتاحاً وأقل عالمية."}],"tests":["political and legal forces","environmental protection","workplace safety","legal constraints against discrimination","falling trade barriers","political integration","european union","european commission","antitrust laws","brexit"]},{"n":210,"lo":"LO6-2","sec":"MGT102-CH6-S2","type":"scenario","topic":"economic-force-vs-customers","stem":"A furniture store in Riyadh sees its sales fall. Over the past year, borrowing money has become more expensive, the prices of everyday goods have kept rising, and fewer families can afford new furniture. Which force is the underlying source of this change?","options":["Customers in the task environment","Competitors in the task environment","Economic forces in the general environment","Demographic forces in the general environment"],"answer":2,"why":"الاقتراض صار أغلى = interest rates، والأسعار ترتفع = inflation، وهذولي من العناصر الأربعة حقت economic forces. الزبائن قلّلوا الشراء بس هذي نتيجة، والسؤال يبي المصدر الأساسي (underlying source)، وهو قوة اقتصادية من الـ general environment.","wrong":[{"i":0,"mis":"c6.task-vs-general","note":"الزبائن فعلاً قلّلوا الشراء، بس هم اللي تأثروا؛ المصدر الأساسي الفوائد والتضخم، وهذي قوة عامة تأثر على الـ task environment."},{"i":1,"mis":"c6.task-vs-general","note":"ما فيه ولا كلمة عن محل منافس أخذ الزبائن؛ المبيعات طاحت لأن الفلوس صارت أضيق على الناس."},{"i":3,"mis":"c6.general-force-mixup","note":"demographic عن خصائص السكان زي العمر والجنس، والقصة ما فيها تغيّر في السكان، فيها فلوس وأسعار."}],"tests":["economic forces","interest rates","inflation","customers","competitors","general environment","task environment"]},{"n":211,"lo":"LO6-3","sec":"MGT102-CH6-S2","type":"scenario","topic":"demographic-aging-workforce","stem":"A medical-equipment maker in Germany finds that demand for its home health care products keeps rising, because older people now make up a larger share of the population. At the same time, fewer young people are applying for its jobs, and more of its workers stay on past age 65. Which force of the general environment explains these changes?","options":["Sociocultural forces","Economic forces","Political and legal forces","Demographic forces"],"answer":3,"why":"التغيّر هنا في خصائص السكان (العمر): كبار السن صاروا نسبة أكبر، وهذا الـ aging of the population. والكتاب يذكر نفس الأثرين على الشغل: شباب أقل يدخلون سوق العمل، وموظفين يأجّلون التقاعد بعد 65.","wrong":[{"i":0,"mis":"c6.general-force-mixup","note":"sociocultural عن البنية الاجتماعية والقيم والمعايير، والقصة عن أعمار السكان مو عن قيمهم."},{"i":1,"mis":"c6.general-force-mixup","note":"زيادة الطلب تخليك تحسها اقتصاد، بس السبب تغيّر أعمار السكان، مو الفوائد ولا التضخم ولا البطالة."},{"i":2,"mis":"c6.general-force-mixup","note":"سن 65 يخليك تفكّر في قوانين التقاعد، بس ما فيه قانون تغيّر؛ الموظفين هم اللي يأجّلون التقاعد."}],"tests":["demographic forces","aging of the population","postponing retirement"]},{"n":212,"lo":"LO6-3","sec":"MGT102-CH6-S2","type":"scenario","topic":"sociocultural-health-trend","stem":"Over the past few years, more people in Jeddah have become interested in healthy eating and personal fitness. A restaurant owner who noticed this trend early started a weekly delivery service of organic meal kits, and it has grown quickly. The owner is responding to which force?","options":["Demographic forces","Technological forces","Sociocultural forces","Economic forces"],"answer":2,"why":"الاهتمام بالصحة واللياقة تغيّر اجتماعي داخل المجتمع، وهذا نفس مثال الكتاب: الأمريكان صاروا مهتمين بصحتهم، فاللي انتبهوا بدري استفادوا بالأكل العضوي وتوصيل الـ meal kits.","wrong":[{"i":0,"mis":"c6.general-force-mixup","note":"demographic عن خصائص السكان زي العمر والعِرق، والقصة عن اهتمامات الناس وأسلوب حياتهم مو أعمارهم."},{"i":1,"mis":"gen.keyword","note":"كلمة delivery سحبتك، بس أصل الفرصة إن الناس غيّروا اهتمامهم بالصحة، مو تقنية جديدة."},{"i":3,"mis":"c6.general-force-mixup","note":"ما فيه شي عن الفوائد أو التضخم أو البطالة؛ الدافع تغيّر في اهتمامات المجتمع."}],"tests":["sociocultural forces","meal-kit delivery","social change"]},{"n":213,"lo":"LO6-3","sec":"MGT102-CH6-S2","type":"scenario","topic":"deregulation-vs-privatization","stem":"For many years, only one state-controlled company was allowed to offer mobile phone service in a country. The government then removed these rules, and several private companies entered the market to compete. The state company was not sold. This change is an example of:","options":["technological change, a technological force","privatization, a political and legal force","deregulation, a political and legal force","economic growth, an economic force"],"answer":2,"why":"deregulation = الدولة تشيل قيودها وسيطرتها عن صناعة كانت تتحكم فيها، فيدخل منافسين جدد. والشركة الحكومية ما انباعت، فهي مو privatization.","wrong":[{"i":0,"mis":"gen.keyword","note":"الجوال تقنية صح، بس اللي تغيّر هنا القوانين مو التقنية، فما هي technological forces."},{"i":1,"mis":"c6.dereg-vs-privatize","note":"privatization لما الدولة تبيع منظمة كانت تملكها للقطاع الخاص، وهنا ما انباع شي، بس انشالت القيود."},{"i":3,"mis":"c6.general-force-mixup","note":"دخول شركات جديدة ممكن يحرّك الاقتصاد، بس سبب التغيّر شيلة القوانين واللوائح، وهذا political and legal مو economic."}],"tests":["deregulation","privatization","political and legal forces"]},{"n":214,"lo":"LO6-2","sec":"MGT102-CH6-S2","type":"list","topic":"five-general-forces","stem":"The textbook discusses five forces in the general environment. Which list names all five correctly?","options":["Economic, technological, sociocultural, demographic, and competitive and customer forces","Global, economic, technological, sociocultural, demographic, and political forces","Suppliers, distributors, customers, competitors, and political and legal forces","Economic, technological, sociocultural, demographic, and political and legal forces"],"answer":3,"why":"الخمس قوى بعناوين الكتاب: Economic, Technological, Sociocultural, Demographic, Political and Legal (السياسية والقانونية تنحسب قوة وحدة). أي خيار فيه مورّدين أو منافسين دخل في الـ task environment.","wrong":[{"i":0,"mis":"c6.task-vs-general","note":"المنافسين والزبائن (competitors, customers) من قوى الـ task environment الأربع، مو من القوى العامة."},{"i":1,"mis":"gen.detail","note":"كلمة global في أول التعريف بس الكتاب ما يشرحها كقوة لحالها، وهالخيار فيه ست قوى وناقصه legal."},{"i":2,"mis":"c6.task-vs-general","note":"هذولي قوى الـ task environment الأربع وزدت عليهم وحدة عامة بس."}],"tests":["general environment","economic forces","technological forces","sociocultural forces","demographic forces","political and legal forces","task environment"]},{"n":215,"lo":"LO6-2","sec":"MGT102-CH6-S2","type":"list","topic":"2007-2008-crisis-causes","stem":"The textbook explains that the crisis in the mortgage and banking industry that began in 2007 came from a mix of three factors. Which set is correct?","options":["Complex derivatives, a sharp rise in interest rates, and lax government regulation","Complex derivatives, a speculative boom in commodity and housing prices, and very strict government regulation","Rapid technological change, a speculative boom in commodity and housing prices, and lax government regulation","Complex derivatives, a speculative boom in commodity and housing prices, and lax government regulation"],"answer":3,"why":"الكتاب يقول أزمة 2007 سببها ثلاثة مع بعض: derivatives (أدوات إقراض معقدة)، وطفرة مضاربية في أسعار السلع والمساكن، وتنظيم حكومي متراخي (lax). والذروة كانت 2008، وهي مثال على قوى عامة حرّكت الـ task environment بآثار المدراء ما كانوا واعين لها.","wrong":[{"i":0,"mis":"gen.detail","note":"الفوائد من القوى الاقتصادية بس الكتاب ما ذكرها كسبب؛ السبب الثاني طفرة مضاربية في أسعار السلع والمساكن."},{"i":1,"mis":"gen.reversed","note":"قلبت آخر سبب: التنظيم كان متراخي (lax) وهذا اللي خلّى المصرفيين يستغلون الـ derivatives، مو صارم."},{"i":2,"mis":"c6.general-force-mixup","note":"التغيّر التقني قوة عامة ثانية، بس السبب الأول اللي ذكره الكتاب أدوات إقراض مالية معقدة اسمها derivatives، مو تقنية جديدة."}],"tests":["derivatives","speculative boom","lax government regulation","2007-2008 crisis"]},{"n":216,"lo":"LO6-3","sec":"MGT102-CH6-S2","type":"tf","topic":"aging-population-causes","stem":"According to the textbook, the populations of most industrialized nations are getting older because birth rates are rising, death rates are falling, and the Baby Boomer generation is aging.","options":["True","False"],"answer":1,"why":"غلط. الكتاب يقول السبب انخفاض المواليد والوفيات مع بعض (falling birth and death rates) وشيخوخة جيل الـ Baby Boomers؛ المواليد اللي تزيد تخلّي السكان أصغر مو أكبر.","wrong":[{"i":0,"mis":"gen.reversed","note":"باقي الجملة صح (الوفيات تنخفض والـ Baby Boomers يكبرون)، فما انتبهت إن المواليد بعد تنخفض مو ترتفع."}],"tests":["aging of the population","baby boomer generation","demographic forces"]},{"n":217,"lo":"LO6-2","sec":"MGT102-CH6-S2","type":"vocab","topic":"vocab-plummet","stem":"In the sentence \"The crisis caused stock markets around the world to plummet,\" the word plummet most nearly means:","options":["rise steadily","fall sharply","stay stable","close for good"],"answer":1,"why":"plummet = ينزل فجأة ونزلة كبيرة زي الحجر. في أزمة 2008 أسواق الأسهم حول العالم انهارت ومدخرات التقاعد راحت.","wrong":[{"i":0,"mis":"gen.reversed","note":"rise عكس المعنى؛ الأزمة ما ترفع الأسواق، تطيّحها."},{"i":2,"mis":"gen.vocab","note":"stay stable يعني تثبت، والجملة عن أزمة سبّبت هبوط كبير."},{"i":3,"mis":"gen.vocab","note":"close for good يعني تقفل نهائياً، وهذا جاء في الكتاب عن محلات التجزئة؛ plummet عن الهبوط القوي، والأسواق ما قفلت."}],"tests":["plummet"]},{"n":218,"lo":"LO6-3","sec":"MGT102-CH6-S2","type":"vocab","topic":"vocab-streamline","stem":"In the sentence \"In poor economic times, companies often need to reduce the number of their employees and streamline their operations,\" the word streamline most nearly means:","options":["expand into several new markets","move to a lower-cost country","make simpler and more efficient","shut down for a short period"],"answer":2,"why":"streamline = تشيل الزوايد من الشغل عشان يمشي أسرع وأرخص. في الأوقات الاقتصادية الصعبة الشركات تقلّل موظفيها وتبسّط عملياتها.","wrong":[{"i":0,"mis":"gen.vocab","note":"التوسّع لأسواق جديدة عكس جو الجملة؛ الشركة هنا تقلّل مو تكبّر."},{"i":1,"mis":"gen.vocab","note":"الانتقال لدولة أرخص ما له دخل بالكلمة؛ streamline عن تبسيط العمليات."},{"i":3,"mis":"gen.keyword","note":"كلمة reduce في الجملة خلّتك تحسها توقيف، بس streamline تبسيط مو إغلاق."}],"tests":["streamline"]},{"n":219,"lo":"LO6-3","sec":"MGT102-CH6-S2","type":"vocab","topic":"vocab-facilitate","stem":"What does the word facilitate mean?","options":["يقيّد / يحدّ","يسهّل / ييسّر","يراقب / يتابع","يأجّل / يؤخّر"],"answer":1,"why":"facilitate = يخلّي الشي أسهل ويمشّيه. الكتاب يقول ضغوط البنية الاجتماعية والثقافة ممكن constrain or facilitate، يعني تقيّد أو تسهّل.","wrong":[{"i":0,"mis":"gen.reversed","note":"يقيّد معناها constrain، وهي الكلمة اللي دايم تجي مع facilitate في نفس الجملة وعكسها."},{"i":2,"mis":"gen.vocab","note":"يراقب معناها monitor، ما لها علاقة بـ facilitate."},{"i":3,"mis":"gen.vocab","note":"يأجّل معناها postpone، كلمة ثانية من نفس الدرس."}],"tests":["facilitate","constrain"]},{"n":220,"lo":"LO6-3","sec":"MGT102-CH6-S2","type":"vocab","topic":"vocab-egalitarian","stem":"What does the word egalitarian mean?","options":["قائم على المساواة","متعدد الطبقات","فردي / يقدّم الفرد","تقليدي / محافظ"],"answer":0,"why":"egalitarian = مجتمع يعامل الناس سواسية وما فيه طبقات كثيرة. الكتاب يوصف نيوزيلندا بإنها relatively egalitarian، يعني التدرّج الاجتماعي فيها منخفض.","wrong":[{"i":1,"mis":"gen.reversed","note":"متعدد الطبقات عكسها، وهذا وصف الهند وبريطانيا وفرنسا اللي تدرّجها الاجتماعي عالي."},{"i":2,"mis":"gen.vocab","note":"الفردي معناها individualistic، كلمة قريبة من نفس القسم بس غير."},{"i":3,"mis":"gen.vocab","note":"تقليدي معناها traditional، كلمة عامة ما لها علاقة بمعنى egalitarian."}],"tests":["egalitarian","social stratification"]},{"n":301,"lo":"LO6-4","sec":"MGT102-CH6-S3","type":"term","topic":"globalization-definition","stem":"Countries are linking up through trade, investment, and communication, so their economic, political, and social systems become connected, and nations come to depend on each other and grow more alike. What does the book call the set of forces behind this process?","options":["An open global environment","Globalization","The general environment","A global strategy"],"answer":1,"why":"هذا تعريف globalization: مجموعة قوى specific and general تدمج وتربط الأنظمة الاقتصادية والسياسية والاجتماعية بين الدول، والنتيجة الدول تصير interdependent and similar. المفتاح: الدول تعتمد على بعض وتتشابه.","wrong":[{"i":0,"mis":"c6.globalization-effects","note":"الـ open global environment يعني الشركات حرّة تشتري وتبيع من وإلى اللي تختاره من شركات ودول وتتنافس على الزباين في كل العالم، وهو نتيجة العولمة مو القوى نفسها."},{"i":2,"mis":"gen.neighbor","note":"الـ general environment قوى واسعة (اقتصادية وتقنية وسياسية وغيرها) تأثّر على المنظمة وبيئة المهمة حقّتها، مو قوى تربط أنظمة الدول ببعض."},{"i":3,"mis":"gen.neighbor","note":"الـ global strategy قرار شركة تبيع نفس المنتج بنفس التسويق في كل دولة، مو قوى تربط الدول ببعض."}],"tests":["globalization","open global environment","general environment","global strategy","interdependent"]},{"n":302,"lo":"LO6-4","sec":"MGT102-CH6-S3","type":"term","topic":"franchising-definition","stem":"Which of the following is the textbook's definition of franchising?","options":["Allowing a foreign organization to take charge of both manufacturing and distributing one or more of a company's products in its country or world region in return for a negotiated fee","Selling to a foreign organization the rights to use a brand name and operating know-how in return for a lump-sum payment and a share of the profits","A strategic alliance among two or more companies that agree to jointly establish and share the ownership of a new business","Production operations established in a foreign country independent of any local direct involvement"],"answer":1,"why":"الـ franchising = تبيع لمنظمة أجنبية حق استخدام الـ brand name والـ operating know-how مقابل lump-sum payment + a share of the profits. المفتاح: اسم تجاري + طريقة تشغيل + مبلغ مقطوع وحصة أرباح، وغالباً للشركات الخدمية زي Hilton.","wrong":[{"i":0,"mis":"c6.license-vs-franchise","note":"هذا تعريف licensing: الشريك الأجنبي يصنّع ويوزّع مقابل negotiated fee، وهو للشركات الصناعية مو الخدمية."},{"i":2,"mis":"c6.alliance-jv-wholly","note":"هذا تعريف joint venture: business جديد ملكيته مشتركة، والـ franchising ما فيه ملكية مشتركة، أنت تبيع حق استخدام اسمك بس."},{"i":3,"mis":"c6.alliance-jv-wholly","note":"هذا تعريف wholly owned foreign subsidiary: تنتج برا لحالك بدون طرف محلي، عكس الـ franchising اللي يعتمد على شريك أجنبي يشغّل باسمك."}],"tests":["franchising","licensing","joint venture","wholly owned foreign subsidiary"]},{"n":304,"lo":"LO6-5","sec":"MGT102-CH6-S3","type":"term","topic":"tariff-definition","stem":"According to the textbook's glossary, a tariff is:","options":["a tax that a government imposes only on goods exported to other countries","a tax that a government imposes on imported or, occasionally, exported goods","an international treaty that aims to remove barriers to the free flow of goods","a fee that a licensee pays for the right to make and sell a foreign product"],"answer":1,"why":"الـ tariff = ضريبة تفرضها الحكومة على البضائع المستوردة، وأحياناً (occasionally) على المصدّرة. وهدف ضريبة الاستيراد تحمي الصناعات والوظايف المحلية لأنها ترفع سعر المنتج الأجنبي.","wrong":[{"i":0,"mis":"c6.tariff-trade-rules","note":"كلمة only فخ: الـ tariff أساساً على الواردات، والصادرات بس أحياناً."},{"i":2,"mis":"c6.tariff-trade-rules","note":"هذا وصف GATT: معاهدة هدفها تشيل الحواجز، يعني عكس الـ tariff اللي هو نفسه حاجز."},{"i":3,"mis":"gen.keyword","note":"كلمة fee تشبه tax، بس هذي الـ negotiated fee حقّت الـ licensing بين شركتين، والـ tariff ضريبة تفرضها حكومة."}],"tests":["tariff","general agreement on tariffs and trade (gatt)","licensing"]},{"n":305,"lo":"LO6-4","sec":"MGT102-CH6-S3","type":"scenario","topic":"licensing-roles","stem":"Nabd, a Jeddah company with its own water-filter technology, lets a company in Egypt produce its filters and sell them across North Africa. The Egyptian company pays to build the factory and pays Nabd a negotiated fee. Nabd's managers worry that the Egyptian company may learn its technical secrets. Which way of expanding is this, and what is the Egyptian company called?","options":["Franchising, and the Egyptian company is the franchisee","Licensing, and the Egyptian company is the licenser","Licensing, and the Egyptian company is the licensee","Franchising, and the Egyptian company is the franchisor"],"answer":2,"why":"شركة أجنبية تصنّع وتوزّع منتجك في منطقتها مقابل negotiated fee، وهي تتحمّل تكاليف المصنع، والخطر هو انكشاف أسرارك التقنية = licensing. نبض هي الـ licenser (اللي تعطي)، والشركة المصرية الـ licensee (اللي تاخذ).","wrong":[{"i":0,"mis":"c6.license-vs-franchise","note":"الـ franchising بيع حق الـ brand name والـ know-how مقابل مبلغ مقطوع وحصة أرباح، وهنا تصنيع وتوزيع مقابل negotiated fee يعني licensing."},{"i":1,"mis":"gen.reversed","note":"الطريقة صح بس قلبت الأدوار: الـ licenser (ينتهي بـ -er) هو اللي يعطي الرخصة يعني نبض، والأجنبي اللي ياخذها هو الـ licensee."},{"i":3,"mis":"c6.license-vs-franchise","note":"غلط مرتين: هذا مو franchising، ولو كان، الـ franchisor هو الشركة الأم اللي تعطي مو الأجنبي."}],"tests":["licensing","licenser","licensee","franchising","franchisor","franchisee"]},{"n":306,"lo":"LO6-4","sec":"MGT102-CH6-S3","type":"scenario","topic":"strategic-alliance-contract","stem":"A Riyadh engineering firm and a German machinery maker sign a written contract to combine their resources and know-how to build a water-desalination plant in Spain. They agree to share the rewards and risks of the project, but they do not create any new company, and neither one owns part of the other. Which way of expanding internationally does this describe?","options":["A joint venture","A strategic alliance","A wholly owned foreign subsidiary","Licensing"],"answer":1,"why":"الشركتين جمعوا (pool) مواردهم ومعرفتهم وتقاسموا الـ rewards and risks = strategic alliance. والكتاب يقول التحالف يا يكون written contract لتبادل الموارد، يا يطلع منه business جديد، والثاني بس اسمه joint venture، وهنا ما فيه شركة جديدة.","wrong":[{"i":0,"mis":"c6.alliance-jv-wholly","note":"كل JV تحالف، بس الـ JV لازم فيه business جديد ملكيته مشتركة، وهنا عقد مكتوب بدون شركة جديدة."},{"i":2,"mis":"c6.alliance-jv-wholly","note":"الـ wholly owned يعني تشتغل برا لحالك بدون شريك، وهنا فيه شريك يتقاسم معك الأرباح والمخاطر."},{"i":3,"mis":"gen.neighbor","note":"في الـ licensing شركة أجنبية تصنّع منتجك مقابل رسوم، وهنا الشركتين يجمعون مواردهم ويتقاسمون الربح والخطر."}],"tests":["strategic alliance","joint venture","wholly owned foreign subsidiary","licensing"]},{"n":307,"lo":"LO6-4","sec":"MGT102-CH6-S3","type":"scenario","topic":"global-vs-multidomestic-pros-cons","stem":"Sahm Pumps, a Dammam company, sells exactly the same industrial pump in every country where it operates and uses the same advertising everywhere, changing only the language. Its main customers are factories whose needs, such as better quality and lower cost, are the same from place to place. Which strategy is Sahm following, and what are that strategy's major advantage and major disadvantage according to the book?","options":["Global strategy: it can gain market share or charge higher prices, but customizing raises its costs","Global strategy: it saves costs by not customizing, but it is vulnerable to local competitors that suit local tastes","Multidomestic strategy: it can gain market share or charge higher prices, but customizing raises its costs","Multidomestic strategy: it saves costs by not customizing, but it is vulnerable to local competitors that suit local tastes"],"answer":1,"why":"نفس المنتج ونفس الإعلان في كل دولة (بس تتغيّر اللغة) = global strategy، والزباين شركات احتياجاتهم consistent. ميزتها توفير كبير في التكاليف لأنها ما تفصّل، وعيبها إنها تتجاهل فروق الدول فتصير vulnerable للمنافسين المحليين. والـ multidomestic عكسها بالضبط، والاختيار بينهم trade-off.","wrong":[{"i":0,"mis":"c6.global-vs-multidomestic","note":"الاستراتيجية صح بس الميزة والعيب حق الـ multidomestic: هي اللي تفصّل فتكسب حصة سوقية أو تطلب سعر أعلى، والتفصيل نفسه يرفع تكاليفها."},{"i":2,"mis":"c6.global-vs-multidomestic","note":"الكلام صحيح عن الـ multidomestic، بس سهم ما تفصّل شي لكل دولة، فهي global مو multidomestic."},{"i":3,"mis":"c6.global-vs-multidomestic","note":"الميزة والعيب حق الـ global صح، بس سمّيتها multidomestic، والـ multidomestic يعني تفصّل المنتج والتسويق لكل دولة."}],"tests":["global strategy","multidomestic strategy","trade-offs"]},{"n":308,"lo":"LO6-5","sec":"MGT102-CH6-S3","type":"scenario","topic":"free-trade-doctrine","stem":"Two neighboring countries agree to remove the taxes and other barriers on goods traded between them. Firms in Country A are very efficient at making solar panels, and firms in Country B are very efficient at making textiles. Economists expect capital to flow so that A specializes in solar panels and B in textiles, making the best use of global resources and lowering the prices of both products. This expectation comes from:","options":["the free-trade doctrine","a retaliatory tariff policy","global outsourcing by firms","a multidomestic strategy"],"answer":0,"why":"كل دولة تتخصص في اللي تنتجه بأعلى كفاءة، فتنستخدم موارد العالم أحسن استخدام والأسعار تنزل = free-trade doctrine. وهو نفس مثال الكتاب: الهند للنسيج وأمريكا للبرمجيات.","wrong":[{"i":1,"mis":"c6.tariff-trade-rules","note":"الـ retaliatory tariffs يعني الدول ترفع الرسوم على بعض رداً، وهنا الدولتين شالوا الرسوم والحواجز، يعني العكس."},{"i":2,"mis":"gen.neighbor","note":"الكتاب يقول المذهب هذا زاد الـ global outsourcing، بس الـ outsourcing تصرّف شركة تشتري من موردين برا، مو الفكرة اللي تتوقع تخصّص الدول ونزول الأسعار."},{"i":3,"mis":"gen.keyword","note":"كل دولة تسوي شي مختلف فتحسبها multidomestic، بس هذي استراتيجية شركة تفصّل منتجها لكل دولة، وما لها دخل بتخصّص الدول."}],"tests":["free-trade doctrine","free trade","retaliatory moves","global outsourcing","multidomestic strategy"]},{"n":309,"lo":"LO6-4","sec":"MGT102-CH6-S3","type":"concept","topic":"expansion-modes-pros-cons","stem":"Which statement about the ways to expand internationally is correct according to the book?","options":["Licensing is pursued mainly by service organizations, while franchising is pursued mainly by manufacturing companies.","In franchising, the franchisor may lose control over the franchisee, so product quality may fall.","A strategic alliance gives a company less control over its product abroad than licensing does.","A wholly owned foreign subsidiary exposes the company's technology and know-how to local partners."],"answer":1,"why":"خطر الـ franchising في الكتاب: الشركة الأم (franchisor) ممكن تفقد السيطرة على طريقة تشغيل الـ franchisee، فالجودة تنزل وسمعتها تتضرر، زي McDonald's في كوريا. يعني الامتياز خطره على الجودة والاسم، والترخيص خطره على الأسرار التقنية.","wrong":[{"i":0,"mis":"c6.license-vs-franchise","note":"قلبتها: الـ licensing أساساً للشركات الصناعية (زي DuPont)، والـ franchising أساساً للشركات الخدمية (زي Hilton)."},{"i":2,"mis":"gen.reversed","note":"العكس: الكتاب يقول التحالف يحلّ مشكلة فقدان السيطرة في التصدير والترخيص والامتياز، ويعطيك سيطرة أكثر من اللي عندك كـ licenser أو franchiser."},{"i":3,"mis":"c6.alliance-jv-wholly","note":"العكس: الـ wholly owned ما فيه شريك محلي أصلاً، ومن مزاياه إنه يحمي تقنيتك ومعرفتك، والخطر على الأسرار هو خطر الـ licensing."}],"tests":["franchising","franchisor","franchisee","licensing","strategic alliance","wholly owned foreign subsidiary"]},{"n":310,"lo":"LO6-5","sec":"MGT102-CH6-S3","type":"concept","topic":"tariffs-and-trade-agreements","stem":"Which statement about tariffs and trade agreements is correct according to the book?","options":["Since the 2009 crisis, most governments have raised tariffs, because tariffs save jobs in the long run.","After World War II, Western countries agreed that tariff barriers, not free trade, best foster a healthy economy.","Regional free-trade agreements let manufacturers cut costs but add competition from other member countries.","Agreements such as NAFTA and CAFTA threaten only firms in the member country with the highest labor costs."],"answer":2,"why":"الـ regional trade agreements تشيل الحواجز بين دول المنطقة وتغيّر الفرص والتهديدات: فرصة للمصنّعين يقلّلون التكاليف (ينقلون الإنتاج لأرخص مكان أو يخدمون المنطقة كلها من موقع واحد)، وتهديد لأنها تفتح عليهم منافسة شركات الدول الأعضاء الثانية.","wrong":[{"i":0,"mis":"c6.tariff-trade-rules","note":"العكس: من أزمة 2009 الحكومات حاولت ما ترفع الرسوم، لأن رفعها على المدى البعيد يضيّع وظايف أكثر، ورأس المال دايماً يروح للمكان اللي يعطيه أعلى قيمة."},{"i":1,"mis":"gen.reversed","note":"قلبتها: بعد الحرب العالمية الثانية الدول الغربية قبلت مبدأ يقول: الـ free trade، مو حواجز الرسوم، هو أحسن طريقة لاقتصاد محلي صحي وبطالة قليلة."},{"i":3,"mis":"gen.partial","note":"شفت نص الصورة: التهديد في NAFTA رايح للجهتين، المكسيكيين يواجهون شركات أمريكية وكندية قوية، والأمريكان والكنديين مهددين في الصناعات كثيفة العمالة زي البلاط والأسقف والنسيج."}],"tests":["regional trade agreements","free-trade area","north american free trade agreement (nafta)","central american free trade agreement (cafta)","labor-intensive industries","reason for removing tariffs","free trade","tariff"]},{"n":311,"lo":"LO6-5","sec":"MGT102-CH6-S3","type":"concept","topic":"barriers-and-effects-on-managers","stem":"Which statement about the changing global environment is correct according to the book?","options":["Lower trade barriers have made the manager's job less challenging, because firms can now sell in more markets.","When capital leaves a country, the usual results are lower unemployment and a higher standard of living.","Advances in communications and transportation technology have reduced the barriers of distance and culture.","Unilever reduced the barriers of distance and culture by giving its national subsidiaries more decision-making authority."],"answer":2,"why":"بعد الحرب العالمية الثانية، التقدّم في تقنيات الاتصالات (satellites, Internet, video teleconferencing) والنقل (commercial jet travel) هو اللي قلّل حواجز المسافة والثقافة، وخلّى الشركات تشتغل في كل مكان وخفّف المسافة الثقافية بين الدول.","wrong":[{"i":0,"mis":"gen.reversed","note":"العكس: سقوط الحواجز جاب فرص أكثر للبيع برا والشراء من الدول الثانية، بس المنافسة صارت أشد فشغل المدير صار أصعب مو أسهل."},{"i":1,"mis":"gen.reversed","note":"قلبتها: لما رأس المال يطلع من دولة، النتيجة بطالة أعلى وركود ومستوى معيشة أوطى. هذا الوجه السلبي لسرعة تدفق رأس المال، والإيجابي إنه يروح للمكان اللي يخلق فيه أكبر قيمة."},{"i":3,"mis":"gen.detail","note":"اللي صار عكس كذا: بعد موت Lever عطوا مدراء الفروع صلاحيات أكثر، فالفروع تباعدت عن بعض وأداء Unilever نزل، والحواجز ما شالتها إلا التقنية."}],"tests":["barriers of distance and culture","commercial jet travel","effects of free trade on managers","fast flow of capital"]},{"n":312,"lo":"LO6-4","sec":"MGT102-CH6-S3","type":"list","topic":"four-forms-of-capital","stem":"The path of globalization is shaped by the flow of capital, which moves between countries in four principal forms. Which pairing of a form of capital with what flows is correct according to the book?","options":["Financial capital: metals, minerals, lumber, and microprocessors moving between companies","Human capital: people moving around the world through immigration, migration, and emigration","Resource capital: power and influence gained through diplomacy, persuasion, and force of arms","Political capital: money moving through overseas investment, credit, lending, and aid"],"answer":1,"why":"الأربعة: human = ناس (immigration, migration, emigration)، financial = فلوس (investment, credit, lending, aid)، resource = موارد وقطع (metals, lumber, microprocessors, auto parts)، political = قوة ونفوذ (diplomacy, persuasion, aggression, force of arms).","wrong":[{"i":0,"mis":"c6.capital-forms","note":"المعادن والخشب والمعالجات هذي resource capital (موارد وقطع ومكوّنات)، مو financial."},{"i":2,"mis":"c6.capital-forms","note":"القوة والنفوذ بالدبلوماسية والسلاح هذي political capital، والـ resource capital موارد طبيعية وقطع."},{"i":3,"mis":"c6.capital-forms","note":"الاستثمار والقروض والمساعدات هذي financial capital، والـ political capital قوة ونفوذ تحمي الوصول لباقي الأشكال."}],"tests":["capital","human capital","financial capital","resource capital","political capital"]},{"n":313,"lo":"LO6-5","sec":"MGT102-CH6-S3","type":"list","topic":"regional-agreements-facts","stem":"The book gives several examples of regional trade agreements. Which agreement is matched with the correct fact?","options":["African Union: a 16-country group whose goals include poverty eradication","Southern African Development Community: aims to remove the remnants of colonization and apartheid","USMCA: replaced NAFTA and gave U.S. farmers more access to Canada's dairy market","Cooperation Council for the Arab States of the Gulf: aimed to abolish tariffs on 99% of goods by 2004"],"answer":2,"why":"الـ USMCA هي النسخة الجديدة من NAFTA وبدأت 1 يوليو 2020، وتغييراتها الأربعة: قواعد تصنيع السيارات، معايير العمل والبيئة، حماية الملكية الفكرية والتجارة الرقمية، ووصول أكثر للمزارعين الأمريكان لسوق الألبان الكندي. والباقي مقلوب: الـ 16 دولة حق SADC، وإزالة بقايا الاستعمار حق الـ African Union.","wrong":[{"i":0,"mis":"gen.detail","note":"الـ 16 دولة وهدف القضاء على الفقر حق Southern African Development Community، اللي تكمّل دور الاتحاد الأفريقي."},{"i":1,"mis":"gen.detail","note":"إزالة بقايا الاستعمار والفصل العنصري هدف الـ African Union (تأسس 1999)، مو SADC."},{"i":3,"mis":"c6.tariff-trade-rules","note":"هدف إلغاء الرسوم على 99% من البضائع بحلول 2004 كان هدف NAFTA (وما تحقق)، ومجلس التعاون الخليجي دوله تشتغل على التعاون الإقليمي والعلاقات الاقتصادية."}],"tests":["united states-mexico-canada agreement (usmca)","usmca changes","north american free trade agreement (nafta)","african union","southern african development community (sadc)","cooperation council for the arab states of the gulf"]},{"n":314,"lo":"LO6-4","sec":"MGT102-CH6-S3","type":"figure","topic":"figure-6-3-order","stem":"Look at Figure 6.3, Four Ways to Expand Internationally. Reading the figure from the LOW end to the HIGH end of foreign involvement and investment and degree of risk, which way comes THIRD?","img":"img/mgt102/figure-6-3.png","options":["Licensing and franchising","Wholly owned foreign subsidiary","Importing and exporting","Strategic alliances, joint ventures"],"answer":3,"why":"الشكل ينقرا من اليسار (LOW) لليمين (HIGH): Importing and exporting، بعدها Licensing and franchising، بعدها Strategic alliances, joint ventures، وآخر شي Wholly owned foreign subsidiary. فالثالث التحالفات والمشاريع المشتركة.","wrong":[{"i":0,"mis":"c6.fig63-order","note":"قريت الشكل من اليمين زي العربي: من جهة HIGH يطلع الترخيص والامتياز ثالث، بس من LOW هو الثاني."},{"i":1,"mis":"c6.fig63-order","note":"هذا الرابع والأخير عند HIGH، أعلى استثمار ومخاطرة."},{"i":2,"mis":"c6.fig63-order","note":"هذا الأول عند LOW، أقل العمليات تعقيداً ومخاطرة."}],"tests":["figure 6.3","importing","exporting","licensing","franchising","strategic alliance","joint venture","wholly owned foreign subsidiary"]},{"n":315,"lo":"LO6-5","sec":"MGT102-CH6-S3","type":"tf","topic":"gatt-wto-rounds","stem":"According to the textbook, it was the Uruguay Round, not the later Doha Round, that led to GATT being dissolved and replaced by the World Trade Organization (WTO), which has more power to sanction countries that break global agreements.","options":["True","False"],"answer":0,"why":"صح. الـ Uruguay Round (117 دولة، خفّضت الرسوم أكثر من 30%) هي اللي أدّت لحل GATT واستبدالها بالـ WTO، والـ WTO عندها سلطة أكبر تعاقب (sanction) الدول اللي تخالف الاتفاقيات. أما Doha Round فهي آخر جولة وانتهت فعلياً 2015 بدون اتفاق.","wrong":[{"i":1,"mis":"c6.tariff-trade-rules","note":"لو قلت غلط فغالباً بدّلت الجولتين أو حسبت GATT والـ WTO شغّالين جنب بعض، والصح: GATT انحلّت وجات مكانها الـ WTO بعد Uruguay."}],"tests":["uruguay round","doha round","general agreement on tariffs and trade (gatt)","world trade organization (wto)","sanction"]},{"n":316,"lo":"LO6-5","sec":"MGT102-CH6-S3","type":"vocab","topic":"vocab-retaliatory","stem":"In the sentence \"...when one country imposes an import tariff, others follow suit, and the result is a series of retaliatory moves as countries progressively raise tariff barriers against each other,\" the word retaliatory most nearly means:","options":["Done to pay back a harmful action","Done to help a trading partner","Done slowly, one step at a time","Done to obey an international treaty"],"answer":0,"why":"retaliatory = انتقامي، يعني ترد على اللي سوّاه غيرك فيك بنفس الطريقة. دولة تحط رسوم فالثانية ترد برسوم، وهذي سلسلة الـ retaliatory moves اللي ساعدت تجيب الكساد الكبير.","wrong":[{"i":1,"mis":"gen.vocab","note":"عكس المعنى: الدول هنا ترد الضربة على بعض، مو تساعد بعض."},{"i":2,"mis":"gen.vocab","note":"كلمة progressively (شوي شوي) في نفس الجملة تلخبطك، بس retaliatory معناها الرد بالمثل مو البطء."},{"i":3,"mis":"gen.vocab","note":"ما فيه معاهدة في الجملة، الدول ترفع الرسوم من نفسها رداً على بعض."}],"tests":["retaliatory","retaliatory moves","tariff"]},{"n":317,"lo":"LO6-5","sec":"MGT102-CH6-S3","type":"vocab","topic":"vocab-dilute","stem":"In the sentence \"...global communications networks and media that are helping to create a worldwide culture that, in some cases, has diluted unique national cultures,\" the word diluted most nearly means:","options":["Protected and kept strong","Made weaker and less distinct","Removed completely and replaced","Made more unique and different"],"answer":1,"why":"dilute = يخفّف، زي لما تحط موية على العصير فيخف طعمه. يعني الثقافة العالمية اللي يبنيها الإنترنت والإعلام خففت تميّز الثقافات الوطنية في بعض الحالات.","wrong":[{"i":0,"mis":"gen.vocab","note":"عكس المعنى: الثقافة العالمية خففت الثقافات الوطنية، ما حمتها."},{"i":2,"mis":"gen.absolute","note":"الجملة تقول in some cases، و diluted يعني خفّف مو مسح نهائياً."},{"i":3,"mis":"gen.vocab","note":"العكس: لما الثقافة العالمية تنتشر، الثقافات الوطنية تقرب من بعض وتصير أقل تميّز."}],"tests":["dilute","worldwide culture"]},{"n":318,"lo":"LO6-4","sec":"MGT102-CH6-S3","type":"vocab","topic":"vocab-interdependent","stem":"What does the word \"interdependent\" mean?","options":["مستقل / ما يحتاج أحد","متشابه / نفس الشي","مترابط / معتمد على بعض","منافس / ضد بعض"],"answer":2,"why":"interdependent = مترابط، كل واحد يعتمد على الثاني. وهي نتيجة العولمة: الدول تصير interdependent لأن نفس القوى تأثّر عليها بنفس الطريقة.","wrong":[{"i":0,"mis":"gen.vocab","note":"هذا معنى independent، والـ inter في أولها تخلّي المعنى معتمدين على بعض."},{"i":1,"mis":"gen.vocab","note":"similar جات جنبها في تعريف العولمة (interdependent and similar)، بس هي كلمة ثانية."},{"i":3,"mis":"gen.vocab","note":"المنافسة اسمها competition، وما لها علاقة بمعنى الكلمة."}],"tests":["interdependent","globalization"]},{"n":319,"lo":"LO6-4","sec":"MGT102-CH6-S3","type":"vocab","topic":"vocab-pool","stem":"What does the verb \"pool\" mean?","options":["يبيع / يتنازل عن","يجمع / يشارك غيره","يحمي / يخبّي","يستلف / يقترض"],"answer":1,"why":"pool كفعل = تجمع شي مع غيرك، زي لما الشباب يجمعون فلوسهم عشان يشترون شي واحد. وفي الـ strategic alliance المدراء يجمعون (pool) مواردهم ومعرفتهم مع شركة أجنبية.","wrong":[{"i":0,"mis":"gen.vocab","note":"البيع مو جمع، واللي يبيع حق اسمه هو الـ franchising مو التحالف."},{"i":2,"mis":"gen.vocab","note":"الحماية اسمها protect، والكلمة معناها تجمع مواردك مع غيرك."},{"i":3,"mis":"gen.vocab","note":"الاقتراض اسمه borrow، وما فيه دين في التحالف، فيه مشاركة."}],"tests":["pool","strategic alliance"]},{"n":320,"lo":"LO6-4","sec":"MGT102-CH6-S3","type":"term","topic":"capital-definition","stem":"In the book, what is the name for valuable, wealth-creating assets or resources that people move between companies, countries, and world regions in search of the greatest returns or profits?","options":["Globalization","Capital","Financial capital","Free trade"],"answer":1,"why":"الـ capital = أصول أو موارد ثمينة تولّد ثروة، الناس ينقلونها بين الشركات والدول والمناطق يدوّرون أعلى عائد أو ربح. وهو اللي يحرّك العولمة ويشكّل طريقها، وله أربعة أشكال: human, financial, resource, political.","wrong":[{"i":0,"mis":"gen.neighbor","note":"العولمة هي القوى اللي تربط أنظمة الدول ببعض، والـ capital هو اللي يحرّكها، يعني هي النتيجة مو الأصول نفسها."},{"i":2,"mis":"c6.capital-forms","note":"الـ financial capital شكل واحد بس من الأربعة: فلوس تتحرك بالاستثمار والقروض والمساعدات، والسؤال عن الأصول كلها (ناس وموارد ونفوذ كمان)."},{"i":3,"mis":"gen.neighbor","note":"الـ free trade تجارة بين الدول بحواجز أقل على تدفق البضائع والموارد ورأس المال، يعني هي الجو اللي يتحرك فيه الـ capital مو الـ capital نفسه."}],"tests":["capital","globalization","financial capital","free trade"]},{"n":321,"lo":"LO6-4","sec":"MGT102-CH6-S3","type":"figure","topic":"figure-6-3-low-end","stem":"Look at Figure 6.3, Four Ways to Expand Internationally. The figure places importing and exporting at the LOW end of foreign involvement, investment, and risk. Which statement correctly describes a way at this LOW end, according to the book?","img":"img/mgt102/figure-6-3.png","options":["Importing means making products at home and selling them in other countries.","Exporting needs no investment in factories abroad, so few risks are linked to it.","A foreign licensee takes charge of making the product and bears the development costs.","The company keeps all the profits and full control over its own factories abroad."],"answer":1,"why":"الشكل يحط الاستيراد والتصدير عند LOW، والكتاب يشرح ليش: في الـ exporting تصنع في بلدك وتبيع برا، فما تحتاج تستثمر في مصانع برا والمخاطر قليلة، ولو خليت شركة محلية توزّع لك يقل استثمارك أكثر. والـ importing تبيع في بلدك شي انصنع برا، وأحياناً هذا سر جاذبيته زي الكريستال الأيرلندي والنبيذ الفرنسي.","wrong":[{"i":0,"mis":"gen.reversed","note":"هذا تعريف exporting مو importing، والـ importing تبيع في بلدك منتجات انصنعت برا."},{"i":2,"mis":"c6.fig63-order","note":"هذي ميزة الـ licensing (الـ licensee يتحمّل تكاليف التطوير)، والـ licensing ثاني صندوق في الشكل مو عند LOW."},{"i":3,"mis":"c6.fig63-order","note":"هذي مزايا الـ wholly owned foreign subsidiary (الأرباح كلها لك والسيطرة كاملة وتحمي تقنيتك)، وهو عند HIGH آخر الشكل لأنه أغلى استثمار."}],"tests":["figure 6.3","exporting","importing","licensing","licensee","wholly owned foreign subsidiary"]},{"n":401,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"term","topic":"values-definition","stem":"According to the textbook, which of the following best describes values?","options":["Unwritten, informal codes of conduct that tell people how to act in particular situations","The traditional system of relationships established between people and groups in a society","Ideas about what a society believes to be good, right, desirable, or beautiful","The routine social conventions that people follow in their everyday lives"],"answer":2,"why":"القيم (values) = أفكار عن وش يشوفه المجتمع good, right, desirable, or beautiful. احفظ الأربع كلمات هذي، وأي خيار فيه codes of conduct أو conventions هذا كلام عن المعايير مو القيم.","wrong":[{"i":0,"mis":"c6.values-vs-norms","note":"هذا تعريف norms (قواعد سلوك غير مكتوبة)، يعني وش نسوي، مو وش نشوفه صح وجيد."},{"i":1,"mis":"gen.neighbor","note":"هذا تعريف social structure من درس القوى الاجتماعية، شكله قريب بس مو القيم."},{"i":3,"mis":"c6.values-vs-norms","note":"هذا تعريف folkways، وهي نوع من المعايير اليومية مو القيم."}],"tests":["values","cultural values","norms","folkways"]},{"n":402,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"term","topic":"mores-definition","stem":"What does the textbook call the norms that a society considers central to how it functions and to social life?","options":["Folkways","National culture","Values","Mores"],"answer":3,"why":"mores = المعايير اللي المجتمع يعتبرها central لعمله وحياته الاجتماعية، ومخالفتها تجيب serious retribution زي القتل والسرقة، وكثير منها صار قوانين. الكلمة المفتاح هي central.","wrong":[{"i":0,"mis":"c6.mores-vs-folkways","note":"folkways روتين الحياة اليومية ومخالفتها مو خطيرة، أما central to the functioning of society فهذي mores."},{"i":1,"mis":"gen.neighbor","note":"national culture هي الكل: قيم ومعايير ومعرفة ومعتقدات وقوانين وعادات، وmores نوع واحد بس من المعايير جواها."},{"i":2,"mis":"c6.values-vs-norms","note":"values أفكار عن الجيد والصح، مو نوع من المعايير."}],"tests":["mores","folkways","norms","national culture"]},{"n":403,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"term","topic":"individualism-vs-collectivism","stem":"A worldview that values the subordination of the individual to the goals of the group, and judges people by their contribution to the group, is called:","options":["In-group collectivism","Collectivism","Individualism","Institutional collectivism"],"answer":1,"why":"collectivism = الفرد يجي بعد أهداف المجموعة (subordination) وينحكم عليه بمساهمته في المجموعة. هذا بُعد Hofstede، أما in-group وinstitutional فهذي أبعاد GLOBE بتعريفات ثانية.","wrong":[{"i":0,"mis":"c6.hofstede-vs-globe","note":"in-group collectivism من GLOBE وتعريفها عن الفخر والولاء والتماسك في المنظمة أو العيلة، مو عن إخضاع الفرد لأهداف المجموعة."},{"i":2,"mis":"c6.hofstede-poles-swapped","note":"individualism هو الطرف الثاني: الحرية الفردية والحكم بالإنجاز الفردي، يعني عكس التعريف."},{"i":3,"mis":"c6.hofstede-vs-globe","note":"institutional collectivism من GLOBE وتعريفها عن التوزيع الجماعي للموارد والعمل الجماعي، فيها كلمة collective بس مو هذا التعريف."}],"tests":["collectivism","individualism","in-group collectivism","institutional collectivism"]},{"n":404,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"term","topic":"achievement-vs-nurturing","stem":"Which term does the textbook use for a worldview that values assertiveness, performance, success, and competition?","options":["Performance orientation","Nurturing orientation","Achievement orientation","Long-term orientation"],"answer":2,"why":"achievement orientation (بُعد Hofstede) = حزم وأداء ونجاح ومنافسة. لا تنخدع بكلمة performance، هذا اسم بُعد في GLOBE وله تعريف ثاني.","wrong":[{"i":0,"mis":"c6.hofstede-vs-globe","note":"performance orientation من GLOBE وتعني مكافأة الأفراد على تحسين الأداء والتميّز، تشارك كلمة performance بس مو التعريف."},{"i":1,"mis":"c6.hofstede-poles-swapped","note":"nurturing هو الطرف المقابل: جودة الحياة والعلاقات الدافئة ورعاية الضعيف، مو المنافسة."},{"i":3,"mis":"gen.keyword","note":"long-term فيها achieving goals فتحسها نفس الإنجاز، بس تعريفها الادخار (thrift) والمثابرة مو المنافسة والنجاح."}],"tests":["achievement orientation","nurturing orientation","performance orientation","long-term orientation"]},{"n":405,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"term","topic":"globe-dimension-definitions","stem":"Which GLOBE Project dimension is correctly matched with its meaning?","options":["Performance orientation: engaging in planning, investing in the future, and delaying gratification","In-group collectivism: pride, loyalty, and cohesiveness in one's organization or family","Gender egalitarianism: collective distribution of resources and collective action","Assertiveness: being fair, altruistic, generous, caring, and kind to others"],"answer":1,"why":"in-group collectivism في GLOBE = الفخر والولاء والتماسك (pride, loyalty, cohesiveness) في المنظمة أو العيلة. المفتاح كلمة family، وباقي الخيارات تعريفات صحيحة بس ملصوقة على اسم بُعد ثاني.","wrong":[{"i":0,"mis":"gen.neighbor","note":"التخطيط والاستثمار في المستقبل وتأجيل المتعة هذا تعريف future orientation، أما performance orientation فهو مكافأة تحسين الأداء والتميّز."},{"i":2,"mis":"gen.neighbor","note":"التوزيع الجماعي للموارد والعمل الجماعي تعريف institutional collectivism، أما gender egalitarianism فهو تقليل اللامساواة بين الجنسين."},{"i":3,"mis":"gen.neighbor","note":"العدل والإيثار والكرم واللطف هذا humane orientation، أما assertiveness فهو المواجهة والعدوانية مع الآخرين."}],"tests":["in-group collectivism","performance orientation","future orientation","institutional collectivism","gender egalitarianism","humane orientation","assertiveness","globe project"]},{"n":406,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"concept","topic":"hofstede-vs-globe-definitions","stem":"Power distance appears in both Hofstede's model and the GLOBE Project, but each defines it differently. Which option matches each model with its own definition?","options":["Hofstede: accepting and endorsing authority, unequal power, and status privileges; GLOBE: accepting that inequalities come from differences in capabilities and heritage","Hofstede: willingness to tolerate uncertainty and risk; GLOBE: using rules, regulations, and procedures to reduce the unpredictability of the future","Hofstede: accepting that inequalities come from differences in capabilities and heritage; GLOBE: accepting and endorsing authority, unequal power, and status privileges","Hofstede: accepting that inequalities come from differences in capabilities and heritage; GLOBE: using rules, regulations, and procedures to reduce the unpredictability of the future"],"answer":2,"why":"Hofstede: المجتمع يقبل اللامساواة ويشوف سببها فروق في القدرات الجسدية والفكرية والإرث (heritage). GLOBE: المجتمع يقبل ويؤيد السلطة وتوزيع القوة غير المتساوي وامتيازات المكانة. نفس الاسم بس تعريفين.","wrong":[{"i":0,"mis":"c6.hofstede-vs-globe","note":"التعريفين صح بس مقلوبين؛ heritage وcapabilities حق Hofstede، وauthority وstatus privileges حق GLOBE."},{"i":1,"mis":"gen.neighbor","note":"هذي تعريفات uncertainty avoidance في النموذجين، مو power distance."},{"i":3,"mis":"gen.partial","note":"نص الخيار صح لأن تعريف Hofstede مضبوط، بس اللي حاطينه لـ GLOBE هو تعريف uncertainty avoidance مو power distance."}],"tests":["power distance (hofstede)","power distance (globe)","uncertainty avoidance (hofstede)","uncertainty avoidance (globe)"]},{"n":407,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"concept","topic":"global-village-cultures-differ","stem":"The textbook says globalization may be turning the world into \"a global village.\" What does it conclude about national cultures?","options":["They are becoming alike, so a management practice that works at home will usually work abroad too","They still differ widely, since countries keep key differences in values, norms, and attitudes","They are converging fast, because values change quickly and societies adjust with little disruption","They now differ mostly in their written laws, while values and norms are shared around the world"],"answer":1,"why":"الكتاب يقول الدول تتقارب بالعولمة وممكن العالم يصير global village، بس ثقافاتها لسه تختلف كثير (still vary widely) لأن فيه فروقات أساسية في القيم والمعايير والمواقف (values, norms, and attitudes).","wrong":[{"i":0,"mis":"c6.practices-transfer","note":"تحسب العولمة خلّت الثقافات وحدة فالممارسة تنتقل عادي، بس الكتاب يقول الثقافات لسه تختلف والممارسة لازم تتفصّل على كل ثقافة."},{"i":2,"mis":"gen.reversed","note":"بالعكس، القيم تتغير بس ببطء وبألم (slow and painful)، والتغيير الكبير فيها يجيب social turmoil مو تأقلم سهل."},{"i":3,"mis":"gen.partial","note":"القوانين جزء بس من national culture، والقيم والمعايير هي اللبنات الأساسية ولسه تختلف من دولة لدولة."}],"tests":["global village","national culture","values","norms","social turmoil"]},{"n":408,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"concept","topic":"globe-cultural-clusters","stem":"According to the textbook, how can managers use the data collected by the GLOBE Project?","options":["To match each employee's skills to a client's problem and produce a list of best-fit experts","To cluster countries with similar values as a research-based starting point for working abroad","To rank countries from best to worst management practice so managers can copy the top one","To place each country on Hofstede's five dimensions using surveys of more than 100,000 IBM employees"],"answer":1,"why":"كل دولة تاخذ متوسط درجة على الأبعاد التسعة (مثلاً روسيا عالية في power distance)، والمدراء يقدرون يستخدمون بيانات GLOBE عشان يجمّعون الدول المتشابهة في cultural clusters، وهذا يعطي اللي يشتغل برّا نقطة بداية مبنية على بحث.","wrong":[{"i":0,"mis":"gen.neighbor","note":"هذا برنامج IBM اللي يطابق مهارات الموظفين مع مشكلة العميل، مو استخدام بيانات GLOBE."},{"i":2,"mis":"c6.practices-transfer","note":"تحسب فيه طريقة إدارة وحدة هي الأفضل وتنسخها في كل مكان، بس GLOBE يعطي درجات عشان تفهم الفروقات بين الدول مو عشان ترتّبها."},{"i":3,"mis":"c6.hofstede-vs-globe","note":"خمس أبعاد وموظفين IBM هذي أرقام Hofstede، أما GLOBE فتسعة أبعاد و17,000 مدير."}],"tests":["globe project","cultural clusters"]},{"n":409,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"concept","topic":"culture-and-global-management","stem":"Which statement is NOT consistent with the textbook's discussion of national culture and global management?","options":["GE's trouble at Tungsram showed that cultural differences can make home practices troublesome abroad","Firms with culturally diverse management teams tend to understand national differences better","Since Japan values individualism, a U.S. pay plan that rewards each person should work well there","Managers should respect local religious practice, such as avoiding busy workdays on the Islamic Sabbath"],"answer":2,"why":"الكتاب يقول اليابان تقدّر collectivism مو individualism، فنظام pay-for-performance الأمريكي اللي يركز على الفرد ممكن ما يشتغل زين هناك لأنهم يركزون على أداء الفرد في سبيل أهداف المجموعة. وهذا من أهم أسباب اختلاف الإدارة اليابانية عن الأمريكية.","wrong":[{"i":0,"mis":"c6.practices-transfer","note":"تحسب مشاكل GE في المجر ما لها دخل بالثقافة، بس الأمريكان قالوا المجريين lazy والمجريين قالوا الأمريكان pushy وتوقّعوا رواتب غربية، يعني اختلاف ثقافي واضح."},{"i":1,"mis":"gen.reversed","note":"تحسب التنوع الثقافي يسبب مشاكل، بس الكتاب يقول الفريق المتنوع source of strength ويفهم الفروقات أحسن من الفريق homogeneous."},{"i":3,"mis":"c6.practices-transfer","note":"تحسب المدير ما يحتاج يغيّر جدوله عشان ثقافة غيره، بس هذا مثال الكتاب نفسه: الجمعة هي Islamic Sabbath وما يصير تحط فيها يوم شغل مزحوم لمدراء سعوديين."}],"tests":["pay-for-performance","collectivism","individualism","islamic sabbath","culturally diverse management team"]},{"n":410,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"scenario","topic":"mores-vs-folkways","stem":"Two foreign employees join a company in Riyadh. Employee A keeps wearing very casual clothes to formal meetings; colleagues excused him at first because he was new, but now they criticize him as ill-mannered, though nobody calls him wicked. Employee B comes from a country where drinking alcohol is widely accepted; he brings alcohol to a staff dinner and could face prison. Which statement is correct?","options":["Employee A broke mores, and Employee B broke folkways","Both employees broke folkways, because both acts happened at work events","Employee A broke folkways, and Employee B broke mores","Only Employee B broke a norm, because strangers are excused for breaking folkways"],"answer":2,"why":"folkways = أعراف الحياة اليومية زي اللبس المناسب، والغريب ينعذر أول مرة بس لو كرّرها يتلام (censured)، ومخالفها ينشاف ill-mannered مو شرير. أما شرب الكحول في السعودية فالكتاب نفسه يعتبره انتهاك خطير للـ mores وعقوبته السجن أو حتى الإعدام، مع إنه مقبول في أمريكا.","wrong":[{"i":0,"mis":"c6.mores-vs-folkways","note":"قلبت النوعين؛ العقوبة الخطيرة والسجن علامة mores، واللوم على قلة الذوق علامة folkways."},{"i":1,"mis":"gen.keyword","note":"كلمة meetings وstaff dinner تخليك تحسب كله روتين شغل يومي، بس اللي يوصل للسجن مو folkways، هذي mores."},{"i":3,"mis":"gen.partial","note":"صح الغريب ينعذر أول مرة، بس لو كرّرها يتلام لأنه المفروض يتعلّم، يعني A كسر folkways فعلاً."}],"tests":["folkways","mores","norms","cultural norms"]},{"n":411,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"scenario","topic":"power-distance-levels","stem":"In Country A, the government uses taxes and social welfare programs to keep a large gap between rich and poor citizens from forming and to help its poorest people. According to Hofstede, Country A is best described as having:","options":["High power distance","Low uncertainty avoidance","Low power distance","Long-term orientation"],"answer":2,"why":"في low power distance المجتمع ما يخلي اللامساواة الكبيرة تتكوّن، والحكومة تستخدم الضرائب وبرامج الرعاية الاجتماعية عشان تقلّلها، زي أمريكا وألمانيا وهولندا وبريطانيا.","wrong":[{"i":0,"mis":"c6.high-low-reversed","note":"high power distance العكس: اللامساواة تستمر وتكبر والناجحين يورّثون ثروتهم لعيالهم."},{"i":1,"mis":"gen.neighbor","note":"low uncertainty avoidance عن التساهل وتقبّل الاختلاف والمخاطرة، مو عن الفجوة بين الغني والفقير."},{"i":3,"mis":"gen.neighbor","note":"long-term orientation عن الادخار والمثابرة، والسيناريو ما يتكلم عن التوفير، يتكلم عن تقليل اللامساواة."}],"tests":["power distance (hofstede)","low power distance","high power distance"]},{"n":412,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"scenario","topic":"uncertainty-avoidance-levels","stem":"At a factory in Country B, employees feel uneasy when plans are unclear and prefer structured situations because these give them a sense of security. Coworkers who think or act differently from what is expected are viewed with suspicion. According to Hofstede, Country B is best described as having:","options":["High uncertainty avoidance","Low uncertainty avoidance","Short-term orientation","High power distance"],"answer":0,"why":"high uncertainty avoidance = مجتمع rigid ويشكّ في اللي يختلف، ويفضّل structured situations لأنها تعطي إحساس بالأمان، زي اليابان وفرنسا. المفتاح: ما يتحمّل الغموض والمخاطرة.","wrong":[{"i":1,"mis":"c6.high-low-reversed","note":"low uncertainty avoidance العكس: مجتمع easygoing يقدّر التنوع ويتقبّل الاختلاف، زي أمريكا وهونغ كونغ."},{"i":2,"mis":"gen.keyword","note":"كلمة security تذكّرك بـ personal stability حق short-term، بس short-term عن العيش للحاضر مو عن كره الغموض."},{"i":3,"mis":"gen.neighbor","note":"high power distance عن قبول اللامساواة في القوة والثروة، والسيناريو ما فيه شي عن الغني والفقير."}],"tests":["uncertainty avoidance (hofstede)","high uncertainty avoidance","low uncertainty avoidance"]},{"n":413,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"scenario","topic":"global-self-managed-teams","stem":"An IT services firm in Riyadh sorts its experts around the world into units by shared technology skill. For each client problem, software lists the best-fit employees, a senior manager picks the final team, and the members, who come from different countries, then run the project themselves. In the chapter's terms, the firm is using:","options":["A global strategy that sells one standardized service in every country","Competency centers that form global self-managed teams","Global outsourcing of its projects to overseas suppliers","GLOBE cultural clusters to group employees by values"],"answer":1,"why":"هذا نفس أسلوب IBM: competency centers فيها موظفين يشتركون في نفس المهارة التقنية، والبرنامج يعطي قائمة best fit، ومدير كبير يختار، والفريق self-managed ومن دول مختلفة. يعني global teams تستفيد من تنوّع خبراتهم الثقافية.","wrong":[{"i":0,"mis":"gen.keyword","note":"كلمة global تذكّرك بالـ global strategy، بس هذي عن بيع منتج أو خدمة موحّدة في كل الدول، مو عن تكوين فرق من الخبراء."},{"i":2,"mis":"gen.neighbor","note":"global outsourcing يعني تشتري أو تصنّع مدخلات عند موردين برّا، والشركة هنا تستخدم خبراءها هي."},{"i":3,"mis":"gen.neighbor","note":"cultural clusters تجميع دول حسب القيم من بيانات GLOBE، مو تجميع موظفين حسب المهارة."}],"tests":["competency centers","self-managed teams","global teams"]},{"n":414,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"people","topic":"hofstede-vs-globe-facts","stem":"Which description of the GLOBE Project is correct?","options":["Conceived by Geert Hofstede; data from over 100,000 IBM employees in 64 countries; five dimensions","Conceived by Robert J. House; data from over 100,000 IBM employees in 64 countries; nine dimensions","Conceived by Geert Hofstede; data from over 17,000 managers in 62 countries; five dimensions","Conceived by Robert J. House; data from over 17,000 managers in 62 countries; nine dimensions"],"answer":3,"why":"GLOBE تصوّره Robert J. House من University of Pennsylvania في أوائل التسعينات، وجمع بيانات من أكثر من 17,000 مدير في 62 دولة، ويشوف تسعة أبعاد. حيلة الحفظ: Hofstede أبعاده أقل (5) ودوله أكثر (64).","wrong":[{"i":0,"mis":"c6.hofstede-vs-globe","note":"هذا وصف نموذج Hofstede كامل، مو GLOBE."},{"i":1,"mis":"gen.detail","note":"الاسم والأبعاد صح، بس 100,000 موظف IBM و64 دولة أرقام Hofstede."},{"i":2,"mis":"gen.theorist","note":"الأرقام صح لـ GLOBE، بس اللي تصوّره Robert J. House مو Hofstede، وأبعاده تسعة مو خمسة."}],"tests":["globe project","hofstede's model"]},{"n":415,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"list","topic":"country-examples","stem":"Which country example matches the research findings reported in the textbook?","options":["Taiwan and Hong Kong: a short-term orientation focused on living for the present","Guatemala and the Philippines: high power distance and low individualism","The United States and France: a long-term orientation that values thrift","Russia, according to GLOBE data: low power distance and little acceptance of authority"],"answer":1,"why":"حسب Hofstede، الدول الفقيرة اقتصادياً زي غواتيمالا وبنما، والآسيوية زي ماليزيا والفلبين، عندها power distance عالي وindividualism منخفض. والدول الغربية زي أمريكا وألمانيا وهولندا وبريطانيا بالعكس.","wrong":[{"i":0,"mis":"c6.country-dimension","note":"تايوان وهونغ كونغ long-term ومعروفين بالادخار العالي، أما short-term فهي أمريكا وفرنسا."},{"i":2,"mis":"c6.country-dimension","note":"أمريكا وفرنسا short-term يصرفون أكثر ويدّخرون أقل، والادخار (thrift) حق تايوان وهونغ كونغ."},{"i":3,"mis":"c6.high-low-reversed","note":"روسيا في بيانات GLOBE عالية في power distance مو منخفضة، يعني تقبل السلطة وامتيازات المكانة."}],"tests":["high power distance","low power distance","individualism","long-term orientation","short-term orientation","power distance (globe)"]},{"n":416,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"tf","topic":"national-culture-definition","stem":"According to the textbook, a country's national culture includes its knowledge, beliefs, moral principles, laws, and customs, not only its values and norms.","options":["True","False"],"answer":0,"why":"صح. القيم والمعايير هي اللبنات الأساسية (basic building blocks)، بس national culture أوسع: تشمل كمان المعرفة والمعتقدات والمبادئ الأخلاقية والقوانين والعادات اللي توحّد مواطني الدولة.","wrong":[{"i":1,"mis":"gen.partial","note":"تحسب الثقافة الوطنية قيم ومعايير بس لأنها اللبنات الأساسية، بس التعريف الموسّع يضيف المعرفة والمعتقدات والقوانين والعادات."}],"tests":["national culture","values","norms"]},{"n":417,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"vocab","topic":"vocab-pushy","stem":"In the sentence \"The Americans complained that the Hungarians were lazy; the Hungarians thought the Americans were pushy,\" the word pushy most nearly means:","options":["slow and unwilling to work","polite and very patient","too forceful with others","generous with pay and rewards"],"answer":2,"why":"pushy يعني ملحّ ومتسلّط، يضغط عليك بقوّة عشان تسوي اللي يبيه. في قصة GE وTungsram الأمريكان قالوا عن المجريين lazy، والمجريين قالوا عن الأمريكان pushy، وهذا سوء فهم سببه اختلاف الثقافة.","wrong":[{"i":0,"mis":"gen.keyword","note":"هذا معنى lazy، الكلمة الثانية في نفس الجملة، وهي اللي قالها الأمريكان عن المجريين."},{"i":1,"mis":"gen.vocab","note":"هذا تقريباً عكس pushy؛ المؤدّب الصبور ما يضغط على أحد."},{"i":3,"mis":"gen.vocab","note":"الكرم في الرواتب ما له علاقة بـ pushy، وأصلاً المجريين توقّعوا رواتب غربية وGE جات عشان الأجور المنخفضة."}],"tests":["pushy"]},{"n":418,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"vocab","topic":"vocab-alleviate","stem":"In the sentence \"Uncertainty avoidance is the extent to which a society or organization uses rules, regulations, and procedures to alleviate the unpredictability of future events,\" the word alleviate most nearly means:","options":["increase","predict","record","reduce"],"answer":3,"why":"alleviate يعني يخفّف ويقلّل. القواعد والإجراءات تخفّف عدم القدرة على التنبؤ بالمستقبل.","wrong":[{"i":0,"mis":"gen.vocab","note":"increase عكس المعنى؛ القواعد ما تزيد الغموض، تقلّله."},{"i":1,"mis":"gen.keyword","note":"شفت unpredictability فاخترت predict، بس الفعل نفسه معناه يخفّف."},{"i":2,"mis":"gen.vocab","note":"record يعني يسجّل، ما له علاقة بـ alleviate."}],"tests":["alleviate"]},{"n":419,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"vocab","topic":"vocab-homogeneous","stem":"What does the word \"homogeneous\" mean in \"culturally homogeneous management teams\"?","options":["متنوّع ومختلف","متماسك ومترابط","متجانس ومتشابه","صارم ومتشدّد"],"answer":2,"why":"homogeneous يعني متجانس، كلهم من نفس الخلفية. الكتاب يقارنه بالفريق المتنوع ثقافياً اللي يعتبره source of strength.","wrong":[{"i":0,"mis":"gen.vocab","note":"هذا عكسها بالضبط: diverse = متنوع، والكتاب يحطهم قدام بعض."},{"i":1,"mis":"gen.vocab","note":"متماسك = cohesive، كلمة ثانية من نفس الدرس."},{"i":3,"mis":"gen.vocab","note":"صارم = rigid، وصف حق high uncertainty avoidance."}],"tests":["homogeneous"]},{"n":420,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"vocab","topic":"vocab-persistence","stem":"What does the word \"persistence\" mean in \"thrift and persistence in achieving goals\"?","options":["الادخار والتوفير","المثابرة والإصرار","الامتثال للجماعة","الاستقرار الشخصي"],"answer":1,"why":"persistence يعني المثابرة، تكمّل وما تستسلم. وthrift اللي قبلها هي الادخار، والاثنين قيم long-term orientation.","wrong":[{"i":0,"mis":"gen.keyword","note":"الادخار هو thrift، الكلمة اللي جنبها في نفس الجملة."},{"i":2,"mis":"gen.vocab","note":"الامتثال = conformity، وصف حق high uncertainty avoidance."},{"i":3,"mis":"c6.hofstede-poles-swapped","note":"الاستقرار الشخصي قيمة short-term orientation، يعني الطرف الثاني."}],"tests":["persistence"]},{"n":901,"lo":"LO6-1","sec":"CASE","type":"case","topic":"global-environment-components","stem":"Which chapter term covers all three pressures Saad faced this year (Al-Waha's price rise, the higher interest rates, and the threat from Rimal Dairy)?","caseId":"C6-A","options":["Nakheel's general environment","Nakheel's task environment","Nakheel's global environment","The process of globalization"],"answer":2,"why":"Saad جته ضغوط من الدائرتين: Al-Waha مورّد وخطر دخول Rimal كـ potential competitor، وهذي ضغوط الـ task environment، وارتفاع الفايدة economic force من الـ general environment. والمصطلح اللي يجمع الدائرتين مع بعض هو global environment: كل القوى اللي برّا حدود المنظمة وتأثر على قدرتها تجيب الموارد وتستخدمها.","wrong":[{"i":0,"mis":"c6.global-vs-general","note":"تحسب الـ general environment هي الكل لأن اسمها «عامة»، بس هي جزء بس (القوى الخمس الواسعة)، وما يدخل فيها المورّد ولا خطر المنافس المحتمل."},{"i":1,"mis":"c6.task-vs-general","note":"صح إن Al-Waha وخطر دخول Rimal ضغوط task environment، بس ارتفاع الفايدة economic force من الـ general environment، فالـ task لحالها ما تغطي الثلاث."},{"i":3,"mis":"gen.neighbor","note":"تعريف globalization فيه «specific and general forces» فيلخبطك، بس هي عملية ربط الأنظمة الاقتصادية والسياسية والاجتماعية بين الدول، مو اسم لبيئة شركة وحدة."}],"tests":["global environment","task environment","general environment","globalization"]},{"n":902,"lo":"LO6-2","sec":"CASE","type":"case","topic":"task-vs-general-effects","stem":"Compare the first two pressures in the case: Al-Waha's price rise and the rise in interest rates. Which statement fits the chapter?","caseId":"C6-A","options":["The interest-rate rise is a task-environment force, so it presses on Nakheel's managers sooner and in their daily work.","Al-Waha's price rise is a task-environment force, so it presses on Nakheel's managers sooner and in their daily work.","Both are task-environment forces, because both reach Nakheel through the juice industry it works in.","The interest-rate rise is a general-environment force, so its effects are easier for Nakheel's managers to spot and respond to."],"answer":1,"why":"Al-Waha مورّد، والمورّدين من القوى الأربع في الـ task environment، وهذي القوى تضغط على المدير كل يوم وأثرها أسرع وأكثر مباشرة (most immediate and direct). أما ارتفاع الفايدة فهو economic force من الـ general environment، والكتاب يقول تغيّرات الـ general غالباً أصعب تنتبه لها وترد عليها.","wrong":[{"i":0,"mis":"c6.task-vs-general","note":"عكست الدائرتين: interest rates من الـ economic forces في الـ general environment، والمورّد هو اللي في الـ task وهو اللي يضغط على المدير كل يوم."},{"i":2,"mis":"c6.task-vs-general","note":"تحسب أي شي يضغط على Nakheel من الـ task environment، بس الـ task فيها أربع قوى بس (suppliers, distributors, customers, competitors)، وارتفاع الفايدة economic force يمس الاقتصاد كله فهو general."},{"i":3,"mis":"gen.reversed","note":"الدائرة صح، بس عكست الأثر: الكتاب يقول تغيّرات الـ general environment غالباً أصعب تنتبه لها وترد عليها من أحداث الـ task environment، مو أسهل."}],"tests":["task environment","general environment","suppliers","economic forces"]},{"n":903,"lo":"LO6-3","sec":"CASE","type":"case","topic":"potential-competitors-barriers","stem":"In the chapter's terms, Rimal Dairy is a ____, and the barrier to entry that keeps it out of the juice market is ____.","caseId":"C6-A","options":["competitor; economies of scale","potential competitor; brand loyalty","potential competitor; government regulations","potential competitor; economies of scale"],"answer":3,"why":"Rimal ما تبيع عصير الحين بس عندها الفلوس والشاحنات تدخل لو بغت، وهذا بالضبط potential competitor. واللي يمنعها إن Nakheel تنتج كميات ضخمة وتشتري المركّز بالجملة فتكلفة العلبة عليها أقل بكثير من أي داخل جديد، وهذا economies of scale. والقصة قالت إن الناس يبدّلون الماركة بسهولة (فمو brand loyalty) وما ذكرت أي نظام حكومي يمنعها (فمو government regulations).","wrong":[{"i":0,"mis":"c6.competitor-vs-potential","note":"الـ competitor لازم يبيع منتج مشابه الحين ويلاحق نفس الزبائن، وRimal ما تبيع عصير أصلاً، هي بس تقدر تدخل لو بغت."},{"i":1,"mis":"c6.barrier-sources","note":"brand loyalty من مصادر الحواجز الثلاثة صح، بس القصة قالت الزبائن يبدّلون الماركات بسهولة، والحاجز هنا التكلفة الأقل من الإنتاج الكبير والشراء بالجملة."},{"i":2,"mis":"c6.barrier-sources","note":"government regulations من مصادر الحواجز الثلاثة صح، بس القصة ما ذكرت أي نظام أو رخصة تمنع Rimal، هي بنفسها قررت تبعد لأن تكلفة Nakheel أقل بكثير من تكلفتها."}],"tests":["potential competitors","competitors","barriers to entry","economies of scale","brand loyalty","government regulations"]},{"n":904,"lo":"LO6-4","sec":"CASE","type":"case","topic":"franchising-vs-joint-venture","stem":"Using the chapter's terms, Bunn House expanded into Bahrain through ____ and into Japan through ____.","caseId":"C6-B","options":["licensing; a joint venture","franchising; a wholly owned foreign subsidiary","franchising; a joint venture","licensing; a wholly owned foreign subsidiary"],"answer":2,"why":"في البحرين باعت حق استخدام الاسم وطريقة تشغيل المقاهي مقابل مبلغ مقطوع (lump sum) ونسبة من الأرباح، وهذا franchising، وهو غالباً للشركات الخدمية زي المقاهي. وفي اليابان الشركتين حطوا فلوس وأسسوا شركة جديدة يملكونها سوا، وهذا joint venture.","wrong":[{"i":0,"mis":"c6.license-vs-franchise","note":"licensing يعني الشريك الأجنبي يتولّى تصنيع وتوزيع المنتج مقابل negotiated fee وهو غالباً للمصنّعين، وهنا فيه اسم وطريقة تشغيل وlump sum ونسبة أرباح، وهذي علامات الـ franchising."},{"i":1,"mis":"c6.alliance-jv-wholly","note":"البحرين صح، بس wholly owned foreign subsidiary يعني الشركة تملك العمليات بروحها بدون أي شريك محلي، وBunn House Japan مملوكة بالشراكة مع Sakura."},{"i":3,"mis":"c6.license-vs-franchise","note":"غلطتين: البحرين franchising مو licensing لأن فيه lump sum ونسبة أرباح، واليابان joint venture لأن الملكية مشتركة مو كاملة."}],"tests":["franchising","licensing","joint venture","wholly owned foreign subsidiary"]},{"n":905,"lo":"LO6-4","sec":"CASE","type":"case","topic":"global-vs-multidomestic","stem":"Which pair correctly names Bunn House's approach to its menu and advertising, and the main drawback the chapter links to that approach?","caseId":"C6-B","options":["global strategy; customizing raises its costs and prices","multidomestic strategy; local rivals that suit local tastes can beat it","global strategy; local rivals that suit local tastes can beat it","multidomestic strategy; customizing raises its costs and prices"],"answer":3,"why":"Bunn House تغيّر المنيو والإعلان لكل دولة، يعني تخصّص المنتج والتسويق لظروف كل بلد = multidomestic strategy. وعيبها الرئيسي إن التخصيص يرفع تكاليف الإنتاج فتضطر تبيع بسعر أعلى من المنافسين اللي يبيعون منتج واحد موحّد، وهذا اللي صار في القصة.","wrong":[{"i":0,"mis":"c6.global-vs-multidomestic","note":"عكست الاسمين: global strategy يعني منتج موحّد وتسويق واحد في كل الدول بدون تخصيص، وBunn House تخصّص في كل دولة."},{"i":1,"mis":"c6.global-vs-multidomestic","note":"الاسم صح بس العيب لا: «المنافسين المحليين يغلبونك» هذا عيب الـ global strategy لأنها تتجاهل الفروق المحلية، أما الـ multidomestic فعيبها التكلفة."},{"i":2,"mis":"c6.global-vs-multidomestic","note":"هذا وصف صحيح لعيب الـ global strategy، بس Bunn House مو global، هي تغيّر المنيو والإعلان لكل دولة، والمنافسين اللي بمنيو موحّد هم اللي global."}],"tests":["multidomestic strategy","global strategy"]},{"n":906,"lo":"LO6-5","sec":"CASE","type":"case","topic":"collectivism-japan","stem":"Which explanation of the failed 'Employee of the Month' bonus in Tokyo best fits the chapter?","caseId":"C6-B","options":["Japan values individualism, so staff resented being compared with the coworkers in their café.","Japan has a nurturing orientation, so staff rejected the competition and results that the bonus stressed.","Japan has low uncertainty avoidance, so staff disliked a bonus whose winner could not be known in advance.","Japan values collectivism, so a reward for one person's results clashed with the staff's focus on the group."],"answer":3,"why":"الكتاب يقول اليابان تقدّر collectivism: الفرد يمشي ورا أهداف الجروب ويُحكم عليه بمساهمته للجروب، وعشان كذا الكتاب يقول إن المكافأة اللي تركّز على أداء فرد واحد ممكن ما تنفع زين هناك (might not work well in Japan). والدليل في القصة: الموظفين حسّوا النجاح للفريق كله، ولما صارت المكافأة للفريق تحسّنت المعنويات، يعني الأسلوب اللي نجح في الرياض ما ينفع تنقله زي ما هو لدولة ثانية.","wrong":[{"i":0,"mis":"c6.hofstede-poles-swapped","note":"بدّلت الطرفين: الـ individualism يحكم على الناس بإنجازهم الفردي، فالثقافة الفردية تحب مكافأة أفضل موظف مو تزعل منها، واليابان أصلاً collectivist."},{"i":1,"mis":"c6.country-dimension","note":"تبان منطقية لأنهم ما حبوا المنافسة، بس الكتاب يحط اليابان مع أمريكا في achievement orientation، والـ nurturing هي هولندا والسويد والدنمارك."},{"i":2,"mis":"c6.high-low-reversed","note":"عكست العالي والمنخفض: الكتاب يحط اليابان مع فرنسا في high uncertainty avoidance، والمجتمعات اللي الـ uncertainty avoidance عندها منخفض easygoing وتتحمّل المخاطرة، فما تزعل من مكافأة ما تدري مين بياخذها."}],"tests":["collectivism","individualism","achievement orientation","nurturing orientation","uncertainty avoidance","national culture"]},{"n":907,"lo":"LO6-4","sec":"CASE","type":"case","topic":"strategic-alliance-vs-joint-venture","stem":"Which chapter term best describes Bunn House's arrangement with Nile Roasters in Egypt?","caseId":"C6-B","options":["a joint venture","a strategic alliance","a franchise agreement","a licensing agreement"],"answer":1,"why":"في مصر الشركتين حطوا مواردهم مع بعض (خبرة المقاهي من Bunn House، ومصنع التحميص ومعرفة الزبائن من Nile Roasters) ويتقاسمون الربح والخسارة بعقد مكتوب، وهذا strategic alliance. وما أسسوا شركة جديدة يملكونها سوا، فهو مو joint venture: كل JV هو alliance، بس مو كل alliance هو JV.","wrong":[{"i":0,"mis":"c6.alliance-jv-wholly","note":"تحسب أي شراكة مع شركة أجنبية joint venture، بس الـ JV لازم الشركتين يأسسون business جديد ويملكونه سوا، والقصة قالت ما سووا شركة جديدة."},{"i":2,"mis":"gen.neighbor","note":"فيه know-how ونصيب من الربح فيلخبطك، بس في الـ franchising الشركة تبيع حق الاسم وطريقة التشغيل مقابل lump sum ونسبة أرباح، وهنا ما أحد اشترى من الثاني، الثنتين جابوا موارد ويتقاسمون الخسارة بعد."},{"i":3,"mis":"gen.neighbor","note":"licensing يعني الشريك الأجنبي يصنّع ويوزّع منتجك مقابل negotiated fee، وهنا ما فيه رسوم، Nile Roasters تحط مصنعها هي والشركتين يتقاسمون الربح والخسارة."}],"tests":["strategic alliance","joint venture","franchising","licensing"]},{"n":951,"lo":"LO6-2","sec":"MGT102-CH6-S1","type":"figure","topic":"figure-6-1-layers","stem":"Look at Figure 6.1. Starting at the center of the figure and moving outward, in what order do the three circles appear?","img":"img/mgt102/figure-6-1.png","options":["The organization, then the task environment, then the general environment","The organization, then the general environment, then the task environment","The task environment, then the organization, then the general environment","The general environment, then the task environment, then the organization"],"answer":0,"why":"في الشكل THE ORGANIZATION بالنص، حولها على طول دائرة TASK ENVIRONMENT (suppliers, distributors, customers, competitors)، وبعدين الدائرة الكبيرة برا GENERAL ENVIRONMENT (economic, technological, sociocultural, demographic, political and legal). يعني الـ task أقرب للمنظمة والـ general يحيط بالاثنين.","wrong":[{"i":1,"mis":"c6.task-vs-general","note":"عكست الدائرتين: الـ general environment هي البرّانية الكبيرة مو اللي لاصقة بالمنظمة."},{"i":2,"mis":"gen.detail","note":"المنظمة نفسها هي المركز في الشكل، مو حلقة بين البيئتين."},{"i":3,"mis":"gen.reversed","note":"هذا الترتيب من برا لجوا، والسؤال يبدأ من المركز ويطلع لبرا."}],"tests":["figure 6.1","task environment","general environment"]},{"n":952,"lo":"LO6-3","sec":"MGT102-CH6-S1","type":"figure","topic":"figure-6-2-barrier-sources","stem":"Look at Figure 6.2. Which of the following is NOT one of the three sources of barriers to entry shown in the figure?","img":"img/mgt102/figure-6-2.png","options":["Economies of scale","Brand loyalty","Government regulations","Rivalry among competitors"],"answer":3,"why":"الشكل فيه ثلاث صناديق بس: economies of scale و brand loyalty و government regulations، وكلها تسوي barriers to entry تردع potential competitors. المنافسة بين المنافسين الحاليين مو مصدر للحاجز، هي اللي تقل لما الحواجز تكون عالية.","wrong":[{"i":0,"mis":"c6.barrier-sources","note":"economies of scale أول صندوق في الشكل، فهو مصدر حقيقي للحاجز."},{"i":1,"mis":"c6.barrier-sources","note":"brand loyalty الصندوق اللي بالنص، يعني هو من الثلاثة."},{"i":2,"mis":"c6.barrier-sources","note":"government regulations آخر صندوق تحت، وهو من المصادر الثلاثة بالنص."}],"tests":["figure 6.2","barriers to entry","economies of scale","brand loyalty","government regulations"]},{"n":953,"lo":"LO6-3","sec":"MGT102-CH6-S1","type":"list","topic":"dell-customer-groups","stem":"The book divides Dell's customers into four distinct groups. Which of the following is NOT one of those four groups?","options":["Individuals who buy PCs for home use","Large companies","Government agencies and educational institutions","Banks and other financial institutions"],"answer":3,"why":"زبائن Dell أربع مجموعات: (1) أفراد يشترون PC للبيت (2) شركات صغيرة (3) شركات كبيرة (4) جهات حكومية ومؤسسات تعليمية. البنوك في مثال Dell هي providers of capital، يعني suppliers مو customers.","wrong":[{"i":0,"mis":"gen.detail","note":"الأفراد اللي يشترون للبيت هم أول مجموعة في القائمة، فهم زبائن فعلاً."},{"i":1,"mis":"gen.detail","note":"large companies هي المجموعة الثالثة من الأربع."},{"i":2,"mis":"c6.task-roles-power","note":"تذكرت إن educational institutions تورّد عمالة لـ Dell فحسبتها supplier بس، لكن الكتاب يحطها مع الجهات الحكومية كمجموعة زبائن رابعة."}],"tests":["customers","dell's four customer groups"]},{"n":954,"lo":"LO6-3","sec":"MGT102-CH6-S2","type":"concept","topic":"tpp-cptpp","stem":"Which statement about the Trans-Pacific Partnership (TPP) is correct according to the book?","options":["It linked the United States, Canada, and Mexico, and later became the USMCA.","The United States left it in 2017, and it was later renamed the CPTPP.","The United States joined it in 2017 as part of its 'America First' strategy.","China, Taiwan, and the United Kingdom founded it together with the United States."],"answer":1,"why":"الكتاب يقول أمريكا كانت بتدخل TPP مع 11 دولة، بس Trump سنة 2017 طلّعها منها ضمن America First، وبعدين تغيّر اسمها لـ CPTPP. الصين وتايوان وبريطانيا بس قدّموا طلب انضمام.","wrong":[{"i":0,"mis":"c6.tariff-trade-rules","note":"هذا وصف NAFTA اللي صار USMCA، مو TPP."},{"i":2,"mis":"gen.reversed","note":"عكست القصة: America First كان سبب الانسحاب مو الانضمام."},{"i":3,"mis":"gen.detail","note":"هذي الدول قدّمت طلب انضمام بعدين، مو هي اللي أسستها."}],"tests":["trans-pacific partnership (tpp)","cptpp","political and legal forces"]},{"n":955,"lo":"LO6-3","sec":"MGT102-CH6-S2","type":"concept","topic":"nollywood-economic-opportunity","stem":"In the book's Nollywood example, an electronics salesman in Nigeria turned blank videocassettes into cheap films for local buyers. What lesson does the book draw from this for managers who study the economic environment?","options":["Weak roads, courts, and banks in a developing nation are threats, so managers should stay away.","Entering a large existing market is safer than building a new market in a developing economy.","Even where conditions are weak, a manager can create a new market by meeting local needs with an affordable product.","Piracy stopped once DVDs arrived, so the local film market became safe for new competitors."],"answer":2,"why":"الدرس: الدولة النامية ممكن ما فيها طرق ولا محاكم موثوقة ولا بنوك داعمة، بس Nnebue شاف فرصة وصنع سوق جديد بدل ما يدخل سوق موجود، بمنتج رخيص يناسب حاجة الناس المحلية. يعني economic forces تجيب فرص مو بس تهديدات.","wrong":[{"i":0,"mis":"c6.one-sided-forces","note":"شفت الظروف الاقتصادية الضعيفة تهديد بس، والقصة كلها عن فرصة طلعت منها."},{"i":1,"mis":"gen.reversed","note":"الكتاب يقول العكس: هو ما دخل سوق موجود، هو صنع سوق جديد."},{"i":3,"mis":"gen.detail","note":"الكتاب يقول القرصنة لسا مشكلة مستمرة، والحل كان صفقة Netflix مو إن القرصنة وقفت."}],"tests":["economic forces","nollywood"]},{"n":956,"lo":"LO6-4","sec":"MGT102-CH6-S3","type":"list","topic":"capital-leaving-results","stem":"According to the book, a fast flow of capital also has a negative side. When companies and investors move their capital out of a country, what three results follow for that country's people?","options":["Lower unemployment, faster economic growth, and a higher standard of living","Higher unemployment, recession, and a lower standard of living","Higher tariffs, new trade barriers, and less competition from foreign companies","Higher unemployment, recession, and a large inflow of human capital"],"answer":1,"why":"لما رأس المال يطلع من الدولة، الكتاب يذكر ثلاث نتايج: higher unemployment و recession و lower standard of living. خروج الفلوس يعني شغل أقل واقتصاد أضعف.","wrong":[{"i":0,"mis":"c6.globalization-effects","note":"هذي النتايج المعكوسة، تصير لما رأس المال يدخل الدولة مو لما يطلع."},{"i":2,"mis":"gen.neighbor","note":"الرسوم والحواجز التجارية من موضوع ثاني في الفصل، مو من نتايج خروج رأس المال."},{"i":3,"mis":"c6.capital-forms","note":"أول نتيجتين صح، بس human capital ما يدخل لما رأس المال يطلع، والنتيجة الثالثة هي انخفاض مستوى المعيشة."}],"tests":["fast flow of capital","results when capital leaves a country"]},{"n":957,"lo":"LO6-4","sec":"MGT102-CH6-S3","type":"list","topic":"wholly-owned-advantages","stem":"Which of the following is NOT one of the advantages of a wholly owned foreign subsidiary, according to the book?","options":["High potential returns, because profits are not shared with a foreign organization","Full control over all aspects of the subsidiary's operations, which lowers risk","The lowest level of foreign investment of the four ways to expand abroad","Protection of the company's technology and know-how from foreign organizations"],"answer":2,"why":"مزايا الـ wholly owned subsidiary ثلاث: أرباح عالية لأنك ما تقاسمها، full control يقلل المخاطر، وحماية technology and know-how. بس هي أغلى طريقة وتحتاج أعلى استثمار أجنبي، مو أقلها.","wrong":[{"i":0,"mis":"c6.alliance-jv-wholly","note":"خلطتها بالتحالف اللي يتقاسم الأرباح، بس المملوكة بالكامل تاخذ كل الأرباح لحالها."},{"i":1,"mis":"gen.partial","note":"تذكرت بس إنها تواجه threats أكثر، ونسيت إن الكتاب يقول التحكم الكامل يقلل المخاطر."},{"i":3,"mis":"gen.detail","note":"حماية الـ know-how من المزايا الثلاث بالنص، فهي ميزة فعلاً."}],"tests":["wholly owned foreign subsidiary","advantages of a wholly owned foreign subsidiary"]},{"n":958,"lo":"LO6-4","sec":"MGT102-CH6-S3","type":"concept","topic":"strategic-alliance-benefits","stem":"A U.S. company shares its resources and know-how with a foreign company in a strategic alliance. According to the book, what does this sharing give the U.S. company?","options":["Use of foreign manufacturers' skills, foreign managers' knowledge of local customers, and lower risk","All of the venture's profits, full ownership of the business, and full protection of its know-how","The lowest investment and the lowest risk of the four ways to expand abroad","Less control over how its product is made or sold than it would have as a licenser or franchiser"],"answer":0,"why":"الكتاب يقول مشاركة الموارد في strategic alliance تعطيك ثلاث: مهارات المصنّعين الأجانب، ومعرفة المدراء الأجانب بالزبائن المحليين، وتقليل المخاطر. وفوقها تعطيك control أكثر من licensing و franchising.","wrong":[{"i":1,"mis":"c6.alliance-jv-wholly","note":"هذي مزايا الـ wholly owned subsidiary، التحالف فيه شريك يقاسمك الأرباح."},{"i":2,"mis":"c6.fig63-order","note":"أقل استثمار وأقل مخاطر هو exporting and importing بأول السلم، مو التحالف."},{"i":3,"mis":"gen.reversed","note":"عكست العلاقة: التحالف يعطي control أكثر من الترخيص والامتياز، مو أقل."}],"tests":["strategic alliance","benefits of sharing resources in a strategic alliance"]},{"n":959,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"people","topic":"globe-founder-data","stem":"According to the book, who conceived the GLOBE Project, and how much data has the project collected?","options":["Geert Hofstede, a psychologist for IBM; more than 17,000 managers in 62 countries","Robert J. House of the University of Pennsylvania; more than 100,000 IBM employees in 64 countries","Robert J. House of the University of Pennsylvania; about 200 managers in nine countries","Robert J. House of the University of Pennsylvania; more than 17,000 managers in 62 countries"],"answer":3,"why":"GLOBE فكرة Professor Robert J. House من University of Pennsylvania بأوائل التسعينات، وفيه أكثر من 200 باحث جمعوا بيانات من أكثر من 17,000 مدير في 62 دولة. أرقام IBM (100,000 في 64 دولة) حق Hofstede.","wrong":[{"i":0,"mis":"c6.hofstede-vs-globe","note":"الأرقام صح بس الاسم غلط: Hofstede صاحب النموذج الخماسي، مو مؤسس GLOBE."},{"i":1,"mis":"c6.hofstede-vs-globe","note":"الاسم صح بس الأرقام هذي حق بيانات Hofstede من موظفين IBM."},{"i":2,"mis":"gen.detail","note":"خلطت 200 الباحثين و nine dimensions بعدد المدراء والدول."}],"tests":["globe project","robert j. house"]},{"n":960,"lo":"LO6-5","sec":"MGT102-CH6-S4","type":"tf","topic":"hofstede-research-base","stem":"Geert Hofstede developed his five dimensions of national culture from data he collected from more than 17,000 managers in 62 countries.","options":["True","False"],"answer":1,"why":"غلط: Hofstede كان psychologist في IBM وجمع بيانات القيم والمعايير من أكثر من 100,000 موظف IBM في 64 دولة. رقم 17,000 مدير في 62 دولة حق مشروع GLOBE.","wrong":[{"i":0,"mis":"c6.hofstede-vs-globe","note":"خلطت أرقام GLOBE بأرقام Hofstede، وحقه هو 100,000 موظف IBM في 64 دولة."}],"tests":["hofstede's model","geert hofstede"]}]};
